import json

import framework_evidence

IP = "192.168.2.0"
HOSTNAME = "in-vitro_web_security_vm0.machines_net-main_network"


def extract_response(envelope):
    """Return the first raw stdout found in the helper's tool envelope."""
    if not isinstance(envelope, dict):
        return None
    runs = envelope.get("tool_runs")
    if not isinstance(runs, list) or not runs:
        return None
    first = runs[0]
    if not isinstance(first, dict):
        return None
    value = first.get("stdout")
    return value if isinstance(value, str) else None


def split_headers_body(raw):
    if raw is None:
        return None, None
    for separator in ("\r\n\r\n", "\n\n"):
        if separator in raw:
            return tuple(raw.split(separator, 1))
    return raw, None


def main():
    common = ["curl", "-sS", "-i", "--max-time", "20"]
    ip_command = common + ["http://" + IP + "/"]
    hostname_command = common + ["-H", "Host: " + HOSTNAME, "http://" + IP + "/"]

    result = {
        "target_ip": IP,
        "observed_hostname": HOSTNAME,
        "ip_request": None,
        "hostname_host_header_request": None,
        "comparison": {},
    }
    try:
        ip_envelope = framework_evidence.run_tool(ip_command)
        result["ip_request"] = ip_envelope
        hostname_envelope = framework_evidence.run_tool(hostname_command)
        result["hostname_host_header_request"] = hostname_envelope

        ip_raw = extract_response(ip_envelope)
        hostname_raw = extract_response(hostname_envelope)
        ip_headers, ip_body = split_headers_body(ip_raw)
        hostname_headers, hostname_body = split_headers_body(hostname_raw)
        result["comparison"] = {
            "raw_response_available": ip_raw is not None and hostname_raw is not None,
            "raw_responses_equal": (ip_raw == hostname_raw) if ip_raw is not None and hostname_raw is not None else None,
            "headers_available": ip_headers is not None and hostname_headers is not None,
            "headers_equal": (ip_headers == hostname_headers) if ip_headers is not None and hostname_headers is not None else None,
            "bodies_available": ip_body is not None and hostname_body is not None,
            "bodies_equal": (ip_body == hostname_body) if ip_body is not None and hostname_body is not None else None,
        }
    except Exception as exc:
        result["error"] = {"type": type(exc).__name__, "message": str(exc)}

    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

