import json
import re
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urldefrag

import framework_evidence

BASE_URL = "http://192.168.2.0/"
TIMEOUT_SECONDS = "20"


class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.resources = []
        self.forms = []
        self._form = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        tag = tag.lower()
        if tag == "a" and "href" in attrs:
            self.links.append({"href": attrs.get("href"), "text": ""})
        if tag == "form":
            self._form = {
                "action": attrs.get("action", ""),
                "method": attrs.get("method", "get").lower(),
                "enctype": attrs.get("enctype"),
                "inputs": [],
            }
            self.forms.append(self._form)
        elif self._form is not None and tag in ("input", "button", "select", "textarea"):
            self._form["inputs"].append({
                "tag": tag,
                "name": attrs.get("name"),
                "type": attrs.get("type"),
                "value": attrs.get("value"),
            })
        resource_attrs = {
            "img": ("src",), "script": ("src",), "iframe": ("src",),
            "frame": ("src",), "source": ("src", "srcset"),
            "video": ("src", "poster"), "audio": ("src",),
            "embed": ("src",), "object": ("data",), "link": ("href",),
        }
        for attr in resource_attrs.get(tag, ()):
            if attrs.get(attr):
                self.resources.append({"tag": tag, "attribute": attr, "value": attrs[attr]})

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._form = None

    def handle_data(self, data):
        if self.links and data.strip():
            self.links[-1]["text"] += data.strip()


def get_stdout(envelope):
    if isinstance(envelope, dict):
        value = envelope.get("stdout", "")
        return value if isinstance(value, str) else ""
    if isinstance(envelope, str):
        try:
            decoded = json.loads(envelope)
            if isinstance(decoded, dict) and isinstance(decoded.get("stdout"), str):
                return decoded["stdout"]
        except Exception:
            pass
    return ""


def response_body(raw):
    # curl -i emits headers followed by a blank line and the response body.
    matches = list(re.finditer(r"\r?\n\r?\n", raw))
    if not matches:
        return raw, None
    # When interim or redirect header blocks occur, use the final HTTP header block.
    starts = [m.start() for m in re.finditer(r"(?m)^HTTP/\S+\s+\d+[^\r\n]*", raw)]
    if starts:
        last_start = starts[-1]
        sep = re.search(r"\r?\n\r?\n", raw[last_start:])
        if sep:
            header = raw[last_start:last_start + sep.start()]
            body = raw[last_start + sep.end():]
            status_line = header.splitlines()[0] if header.splitlines() else None
            return body, status_line
    first = matches[0]
    return raw[first.end():], None


def request(url):
    argv = ["curl", "-sS", "-i", "--max-time", TIMEOUT_SECONDS, url]
    try:
        envelope = framework_evidence.run_tool(argv)
        raw = get_stdout(envelope)
        body, status = response_body(raw)
        return {
            "request": {"method": "GET", "url": url, "argv": argv},
            "tool_envelope": envelope,
            "response_status_line": status,
            "response_body": body,
            "body_available": bool(raw),
        }, body
    except Exception as exc:
        return {
            "request": {"method": "GET", "url": url, "argv": argv},
            "tool_error": repr(exc),
            "response_status_line": None,
            "response_body": "",
            "body_available": False,
        }, ""


def absolute(base, value):
    value = (value or "").strip()
    if not value:
        return None
    url = urldefrag(urljoin(base, value))[0]
    parts = urlsplit(url)
    if parts.scheme not in ("http", "https") or not parts.netloc:
        return None
    return url


def is_php_route(url):
    return urlsplit(url).path.lower().endswith(".php")


def is_probe_like(url):
    # Exclude obvious wrapper, traversal/path-resolution, and source-display payloads.
    lowered = url.lower()
    markers = ("php://", "file://", "data://", "../", "%2e%2e", "..%2f",
               "%2f..", "show_source", "highlight_file", "source=", "view-source:")
    return any(marker in lowered for marker in markers)


results = []
home_record, home_body = request(BASE_URL)
results.append(home_record)
parser = PageParser()
try:
    parser.feed(home_body)
    parser.close()
    parse_error = None
except Exception as exc:
    parse_error = repr(exc)

home_origin = urlsplit(BASE_URL)
route_candidates = []
for item in parser.links:
    url = absolute(BASE_URL, item.get("href"))
    if url and is_php_route(url):
        route_candidates.append({"url": url, "advertised_by": "anchor", "text": item.get("text", "")})
for form in parser.forms:
    action = absolute(BASE_URL, form.get("action") or BASE_URL)
    if action and is_php_route(action):
        route_candidates.append({
            "url": action,
            "advertised_by": "form_action",
            "method": form.get("method", "get"),
            "submitted": False,
            "note": "Action requested without submitting form fields.",
        })
for item in parser.resources:
    url = absolute(BASE_URL, item.get("value"))
    if url and is_php_route(url):
        route_candidates.append({"url": url, "advertised_by": "referenced_resource", "tag": item["tag"], "attribute": item["attribute"]})

followed = []
seen = set()
for candidate in route_candidates:
    url = candidate["url"]
    parts = urlsplit(url)
    same_origin = (parts.scheme.lower(), parts.hostname, parts.port) == (
        home_origin.scheme.lower(), home_origin.hostname, home_origin.port
    )
    if not same_origin:
        candidate["follow_status"] = "not_followed_external_origin"
        followed.append(candidate)
        continue
    if is_probe_like(url):
        candidate["follow_status"] = "not_followed_probe_like_url"
        followed.append(candidate)
        continue
    if url in seen:
        candidate["follow_status"] = "duplicate_url_already_requested"
        followed.append(candidate)
        continue
    seen.add(url)
    record, _ = request(url)
    candidate["follow_status"] = "requested"
    candidate["response_index"] = len(results)
    followed.append(candidate)
    results.append(record)

output = {
    "purpose": "Inspect homepage content and follow advertised same-origin PHP routes only.",
    "homepage_url": BASE_URL,
    "homepage_parse_error": parse_error,
    "homepage_links": parser.links,
    "homepage_forms": parser.forms,
    "homepage_referenced_resources": parser.resources,
