import base64
import json
import re
import urllib.error
import urllib.parse
import urllib.request
from html.parser import HTMLParser

HOME = "http://192.168.2.0/"
ORIGIN = ("http", "192.168.2.0", 80)
REQUEST_HEADERS = {
    "User-Agent": "RouteInspection/1.0",
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
}


def same_origin(url):
    p = urllib.parse.urlsplit(url)
    try:
        port = p.port or (443 if p.scheme.lower() == "https" else 80)
    except ValueError:
        return False
    return (p.scheme.lower(), (p.hostname or "").lower(), port) == ORIGIN


class SameOriginRedirects(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        absolute = urllib.parse.urljoin(req.full_url, newurl)
        if not same_origin(absolute):
            raise urllib.error.HTTPError(req.full_url, code, "cross-origin redirect not followed", headers, fp)
        return super().redirect_request(req, fp, code, msg, headers, absolute)


opener = urllib.request.build_opener(SameOriginRedirects())


def request_get(url):
    req = urllib.request.Request(url, headers=REQUEST_HEADERS, method="GET")
    record = {
        "request": {"method": "GET", "url": url, "headers": REQUEST_HEADERS.copy()},
    }
    try:
        with opener.open(req, timeout=15) as response:
            body = response.read()
            record["response"] = {
                "status": response.status,
                "reason": response.reason,
                "final_url": response.geturl(),
                "headers": list(response.headers.items()),
                "body_base64": base64.b64encode(body).decode("ascii"),
                "body_text": body.decode(response.headers.get_content_charset() or "utf-8", errors="replace"),
            }
    except urllib.error.HTTPError as exc:
        body = exc.read()
        record["response"] = {
            "status": exc.code,
            "reason": exc.reason,
            "final_url": exc.geturl(),
            "headers": list(exc.headers.items()) if exc.headers else [],
            "body_base64": base64.b64encode(body).decode("ascii"),
            "body_text": body.decode("utf-8", errors="replace"),
        }
    except Exception as exc:
        record["error"] = {"type": type(exc).__name__, "message": str(exc)}
    return record


class PageParser(HTMLParser):
    RESOURCE_ATTRS = {
        "script": ("src",), "img": ("src",), "iframe": ("src",),
        "frame": ("src",), "source": ("src",), "audio": ("src",),
        "video": ("src", "poster"), "embed": ("src",), "object": ("data",),
    }

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.resources = []
        self.forms = []
        self._form = None

    def handle_starttag(self, tag, attrs):
        self._handle(tag, attrs)

    def handle_startendtag(self, tag, attrs):
        self._handle(tag, attrs)
        if tag.lower() == "form":
            self._form = None

    def _handle(self, tag, attrs):
        tag = tag.lower()
        a = dict(attrs)
        if tag == "a" and a.get("href") is not None:
            self.links.append({"href": a.get("href"), "text": "", "attributes": a})
        if tag == "form":
            self._form = {"attributes": a, "controls": []}
            self.forms.append(self._form)
        elif self._form is not None and tag in ("input", "button", "select", "textarea"):
            self._form["controls"].append({"tag": tag, "attributes": a})
        if tag == "link" and a.get("href") is not None:
            self.resources.append({"tag": tag, "attribute": "href", "url": a["href"], "rel": a.get("rel")})
        for attr in self.RESOURCE_ATTRS.get(tag, ()):
            if a.get(attr) is not None:
                self.resources.append({"tag": tag, "attribute": attr, "url": a[attr]})

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._form = None

    def handle_data(self, data):
        if self.links and data.strip():
            self.links[-1]["text"] += data.strip()


def absolute_reference(base, value):
    return urllib.parse.urljoin(base, value.strip())


def route_is_previously_checked(url):
    path = urllib.parse.urlsplit(url).path.rstrip("/").lower()
    return re.search(r"(?:^|/)page[123]\.php$", path) is not None


def main():
    homepage = request_get(HOME)
    result = {
        "target": HOME,
        "scope": "Same-origin HTTP application at 192.168.2.0; no forms are submitted.",
        "homepage": homepage,
        "homepage_links": [],
        "forms": [],
        "referenced_resources": [],
        "advertised_php_routes": [],
        "route_results": [],
        "resource_results": [],
        "limitations": [],
    }
    response = homepage.get("response")
    if not response or "body_text" not in response:
        result["limitations"].append("Homepage response body was unavailable; advertised content could not be extracted.")
        print(json.dumps(result, ensure_ascii=False))
        return

    parser = PageParser()
    try:
        parser.feed(response["body_text"])
        parser.close()
    except Exception as exc:
        result["limitations"].append("HTML parsing error: " + type(exc).__name__ + ": " + str(exc))
    result["forms"] = parser.forms

    base_url = response.get("final_url", HOME)
    # Honor a same-origin HTML base URL when resolving advertised references.
    for match in re.finditer(r"<base\b[^>]*\bhref\s*=\s*(['\"])(.*?)\1", response["body_text"], re.I | re.S):
        candidate = absolute_reference(base_url, match.group(2))
        if same_origin(candidate):
            base_url = candidate
        break

    route_urls = []
    for link in parser.links:
        raw = link.get("href", "")
        resolved = absolute_reference(base_url, raw) if raw else ""
        link["resolved_url"] = resolved
        link["same_origin"] = bool(resolved and same_origin(resolved))
        if resolved and same_origin(resolved) and urllib.parse.urlsplit(resolved).path.lower().endswith(".php"):
            if route_is_previously_checked(resolved):
                link["route_action"] = "not requested; previously checked page1/page2/page3 route"
            else:
                link["route_action"] = "advertised PHP route"
                if resolved not in route_urls:
                    route_urls.append(resolved)
        else:
            link["route_action"] = "not followed as an advertised same-origin PHP route"
    result["homepage_links"] = parser.links

    resource_urls = []
    for item in parser.resources:
        raw = item.get("url", "")
        resolved = absolute_reference(base_url, raw) if raw else ""
        item["resolved_url"] = resolved
        item["same_origin"] = bool(resolved and same_origin(resolved))
        if resolved and same_origin(resolved):
            if resolved not in resource_urls:
                resource_urls.append(resolved)
            item["request_action"] = "GET same-origin referenced resource"
        else:
            item["request_action"] = "URL recorded; not fetched because it is not same-origin or is empty"
    result["referenced_resources"] = parser.resources
    result["advertised_php_routes"] = route_urls

    cache = {}
    for url in route_urls:
        cache[url] = request_get(url)
        result["route_results"].append(cache[url])
    for url in resource_urls:
        if url not in cache:
            cache[url] = request_get(url)
        result["resource_results"].append({"url": url, "result": cache[url], "reused_route_response": url in route_urls})

    if not parser.links and not parser.forms and not parser.resources:
        result["limitations"].append("No links, forms, or referenced resources were extracted from the returned homepage body; inspect the captured body and parser coverage.")
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

