import hashlib
import json
import urllib.error
import urllib.parse
import urllib.request
from html.parser import HTMLParser

HOME = "http://192.168.2.0/"
TIMEOUT = 12
CHECKED_PATHS = {"/page1.php", "/page2.php", "/page3.php"}


class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.forms = []
        self.resources = []
        self.base_href = None
        self._form = None

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        tag = tag.lower()
        if tag == "base" and a.get("href") and self.base_href is None:
            self.base_href = a["href"]
        if tag == "a" and a.get("href") is not None:
            self.links.append({"href": a["href"], "text": ""})
        if tag == "form":
            self._form = {"action": a.get("action", ""), "method": a.get("method", "get").lower(), "fields": []}
            self.forms.append(self._form)
        if self._form is not None and tag in {"input", "select", "textarea", "button"}:
            self._form["fields"].append({"tag": tag, "name": a.get("name"), "type": a.get("type"), "value": a.get("value")})
        ref = None
        if tag == "link":
            ref = a.get("href")
        elif tag in {"script", "img", "iframe", "audio", "source", "track", "embed"}:
            ref = a.get("src")
        elif tag == "video":
            ref = a.get("src") or a.get("poster")
        elif tag == "object":
            ref = a.get("data")
        if ref:
            self.resources.append({"tag": tag, "url": ref, "rel": a.get("rel")})

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._form = None

    def handle_data(self, data):
        if self.links and data.strip():
            self.links[-1]["text"] = (self.links[-1]["text"] + " " + data.strip()).strip()


class SameOriginRedirect(urllib.request.HTTPRedirectHandler):
    def __init__(self, origin):
        super().__init__()
        self.origin = origin

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        if origin_of(newurl) != self.origin:
            return None
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def origin_of(url):
    p = urllib.parse.urlsplit(url)
    scheme = p.scheme.lower()
    port = p.port or (443 if scheme == "https" else 80)
    return scheme, (p.hostname or "").lower(), port


def response_record(url, kind):
    record = {"kind": kind, "request": {"method": "GET", "url": url}}
    req = urllib.request.Request(url, headers={"User-Agent": "route-inspection/1.0", "Accept": "*/*"})
    try:
        with opener.open(req, timeout=TIMEOUT) as response:
            status = response.status
            final_url = response.geturl()
            headers = dict(response.headers.items())
            body = response.read()
    except urllib.error.HTTPError as exc:
        status = exc.code
        final_url = exc.geturl()
        headers = dict(exc.headers.items()) if exc.headers else {}
        try:
            body = exc.read()
        except Exception:
            body = b""
    except Exception as exc:
        record["error"] = {"type": type(exc).__name__, "message": str(exc)}
        return record
    record["response"] = {
        "status": status,
        "final_url": final_url,
        "headers": {k: v for k, v in headers.items() if k.lower() in {"content-type", "content-length", "location", "last-modified"}},
        "body_bytes": len(body),
        "body_sha256": hashlib.sha256(body).hexdigest(),
    }
    decoded = body.decode("utf-8", errors="replace")
    if len(decoded) <= 6000:
        record["response"]["body"] = decoded
        record["response"]["body_truncated"] = False
    else:
        record["response"]["body_excerpt"] = decoded[:2500] + "\n...[body omitted; see byte count and SHA-256]...\n" + decoded[-500:]
        record["response"]["body_truncated"] = True
    record["_body"] = body
    return record


def resolve(base, ref):
    return urllib.parse.urldefrag(urllib.parse.urljoin(base, ref))[0]


opener = urllib.request.build_opener(SameOriginRedirect(origin_of(HOME)))
visited = {}

home_record = response_record(HOME, "homepage")
visited[HOME] = home_record
output = {"target": HOME, "homepage": {}, "links": [], "forms": [], "referenced_resources": [], "advertised_php_routes": [], "limitations": []}
if "response" not in home_record:
    output["homepage"] = home_record
    output["limitations"].append("Homepage response unavailable; page contents and advertised coverage could not be inspected.")
    print(json.dumps(output, ensure_ascii=False, separators=(",", ":")))
    raise SystemExit(0)

body = home_record.pop("_body", b"")
output["homepage"] = home_record
parser = PageParser()
parser.feed(body.decode("utf-8", errors="replace"))
page_base = resolve(home_record["response"].get("final_url", HOME), parser.base_href) if parser.base_href else home_record["response"].get("final_url", HOME)

for item in parser.links:
    item["url"] = resolve(page_base, item["href"])
    output["links"].append(item)
for form in parser.forms:
    form["action_url"] = resolve(page_base, form["action"] or page_base)
    output["forms"].append(form)
for item in parser.resources:
    item["resolved_url"] = resolve(page_base, item["url"])
    output["referenced_resources"].append(item)

origin = origin_of(HOME)
route_urls = []
for item in output["links"]:
    u = item["url"]
    p = urllib.parse.urlsplit(u)
    if origin_of(u) != origin:
        continue
    if p.path.lower().endswith(".php"):
        if p.path.lower() in CHECKED_PATHS and not p.query:
            output["advertised_php_routes"].append({"url": u, "action": "reused_existing_observation_not_requested", "path": p.path})
        else:
            route_urls.append(u)

for url in dict.fromkeys(route_urls):
    result = response_record(url, "advertised_php_route")
    visited[url] = result
    result.pop("_body", None)
    output["advertised_php_routes"].append(result)

for item in output["referenced_resources"]:
    url = item["resolved_url"]
    if origin_of(url) != origin:
        item["inspection"] = "not_fetched_cross_origin"
        continue
    parsed = urllib.parse.urlsplit(url)
    if parsed.path.lower() in CHECKED_PATHS and not parsed.query:
        item["inspection"] = "not_fetched_previously_checked_php_route"
        continue
    if url not in visited:
        visited[url] = response_record(url, "referenced_resource")
    record = visited[url]
    record.pop("_body", None)
    item["response"] = record

for url, record in visited.items():
    if "error" in record:
        output["limitations"].append("Request failed for " + url + ": " + record["error"]["type"] + ": " + record["error"]["message"])
    elif record.get("response", {}).get("status", 0) >= 400:
        output["limitations"].append("HTTP response status " + str(record["response"]["status"]) + " for " + url)

output["forms_not_submitted"] = True
output["previously_checked_routes"] = ["/page1.php", "/page2.php", "/page3.php"]
print(json.dumps(output, ensure_ascii=False, separators=(",", ":")))

