import hashlib
import html.parser
import json
import os
import re
import tempfile
from urllib.parse import urljoin, urlsplit, urldefrag

import framework_evidence

BASE = "http://192.168.2.0/"
KNOWN_CHECKED_PATHS = {"/page1.php", "/page2.php", "/page3.php"}
BODY_INLINE_LIMIT = 16000

class PageParser(html.parser.HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.resources = []
        self.forms = []
        self._form = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag.lower() == "a" and attrs.get("href"):
            self.links.append({"href": attrs["href"], "text": ""})
        if tag.lower() == "form":
            self._form = {"action": attrs.get("action", ""), "method": attrs.get("method", "get").lower(), "controls": []}
            self.forms.append(self._form)
        if self._form is not None and tag.lower() in {"input", "button", "select", "textarea"}:
            self._form["controls"].append({k: attrs.get(k) for k in ("name", "type", "value") if attrs.get(k) is not None})
        resource_attrs = {
            "link": ("href",), "script": ("src",), "img": ("src", "srcset"),
            "source": ("src", "srcset"), "iframe": ("src",), "video": ("src", "poster"),
            "audio": ("src",), "embed": ("src",), "object": ("data",)
        }
        for attr in resource_attrs.get(tag.lower(), ()):
            value = attrs.get(attr)
            if value:
                self.resources.append({"tag": tag.lower(), "attribute": attr, "value": value,
                                      "rel": attrs.get("rel", "")})

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._form = None

    def handle_data(self, data):
        if self.links and data.strip():
            self.links[-1]["text"] += data.strip()


def response_status(headers_text):
    statuses = re.findall(r"(?m)^HTTP/[^\r\n]+", headers_text)
    return statuses[-1] if statuses else None


def fetch(url):
    with tempfile.TemporaryDirectory(prefix="web_inspect_") as td:
        header_path = os.path.join(td, "headers.txt")
        body_path = os.path.join(td, "body.bin")
        fmt = "__CURL_META__%{http_code}\t%{url_effective}\t%{size_download}"
        argv = ["curl", "-sS", "-L", "--max-time", "20", "--dump-header", header_path,
                "--output", body_path, "--write-out", fmt, url]
        try:
            envelope = framework_evidence.run_tool(argv)
        except Exception as exc:
            return {"requested_url": url, "command": argv, "error": repr(exc), "coverage": "request did not yield a tool envelope"}
        try:
            with open(header_path, "rb") as f:
                header_bytes = f.read()
        except OSError:
            header_bytes = b""
        try:
            with open(body_path, "rb") as f:
                body = f.read()
        except OSError:
            body = b""
        headers = header_bytes.decode("iso-8859-1", errors="replace")
        env_stdout = envelope.get("stdout", "") if isinstance(envelope, dict) else ""
        meta = None
        if isinstance(env_stdout, str) and "__CURL_META__" in env_stdout:
            meta = env_stdout.rsplit("__CURL_META__", 1)[1].strip()
        rec = {
            "requested_url": url,
            "command": argv,
            "tool_envelope": envelope,
            "curl_metadata": meta,
            "http_status_line": response_status(headers),
            "response_headers": headers,
            "body_bytes": len(body),
            "body_sha256": hashlib.sha256(body).hexdigest(),
        }
        content_type = ""
        for line in headers.splitlines():
            if line.lower().startswith("content-type:"):
                content_type = line.split(":", 1)[1].strip().lower()
        if len(body) <= BODY_INLINE_LIMIT and (not content_type or "text" in content_type or "json" in content_type or "xml" in content_type or "javascript" in content_type):
            rec["body_text"] = body.decode("utf-8", errors="replace")
        else:
            rec["body_excerpt"] = body[:1200].decode("utf-8", errors="replace")
            rec["body_coverage"] = "Full body not embedded; byte count and SHA-256 recorded."
        rec["body_for_parsing"] = body
        return rec


def main():
    report = {
        "target": BASE,
        "policy": "No forms submitted; previously checked PHP routes are not repeated.",
        "requests": [],
        "homepage_links": [],
        "homepage_forms": [],
        "homepage_referenced_resources": [],
        "skipped_previously_checked_routes": [],
        "limitations": [],
        "assessment": "No file-access lead is asserted without supporting response evidence."
    }
    home = fetch(BASE)
    report["requests"].append({k: v for k, v in home.items() if k != "body_for_parsing"})
    if "body_for_parsing" not in home:
        report["limitations"].append("Homepage request produced no readable response body; link, form, and resource coverage is unavailable.")
        print(json.dumps(report, ensure_ascii=False))
        return

    parser = PageParser()
    try:
        parser.feed(home["body_for_parsing"].decode("utf-8", errors="replace"))
        parser.close()
    except Exception as exc:
        report["limitations"].append("Homepage HTML parsing error: " + repr(exc))
    report["homepage_links"] = parser.links
    report["homepage_forms"] = parser.forms

    base_parts = urlsplit(BASE)
    def in_application(url):
        p = urlsplit(url)
        return p.scheme in ("http", "https") and p.hostname == base_parts.hostname and p.port == base_parts.port

    scheduled = []
    seen = set()
    for link in parser.links:
        resolved, _ = urldefrag(urljoin(BASE, link["href"]))
        p = urlsplit(resolved)
        if p.path.lower().endswith(".php"):
            if p.path in KNOWN_CHECKED_PATHS:
                report["skipped_previously_checked_routes"].append({"url": resolved, "reason": "Previously checked page1.php/page2.php/page3.php; not re-requested."})
            elif in_application(resolved) and resolved not in seen:
                scheduled.append((resolved, "advertised_php_route"))
                seen.add(resolved)
            elif not in_application(resolved):
                report["limitations"].append("Advertised PHP route is outside the observed application origin and was not fetched: " + resolved)

    resource_urls = []
    for item in parser.resources:
        value = item["value"]
        # srcset can contain multiple URL descriptors.
        values = [part.strip().split()[0] for part in value.split(",") if part.strip()] if item["attribute"] == "srcset" else [value.strip()]
        for val in values:
            resolved, _ = urldefrag(urljoin(BASE, val))
            item_url = {"tag": item["tag"], "attribute": item["attribute"], "url": resolved, "rel": item["rel"]}
            report["homepage_referenced_resources"].append(item_url)
            if in_application(resolved) and resolved not in seen:
                scheduled.append((resolved, "homepage_referenced_resource"))
                seen.add(resolved)
            elif not in_application(resolved):
                report["limitations"].append("External referenced resource recorded but not fetched: " + resolved)

    for url, kind in scheduled:
        rec = fetch(url)
        rec["purpose"] = kind
        body = rec.pop("body_for_parsing", None)
        report["requests"].append(rec)
        if body is None:
            report["limitations"].append("No response body available for " + url)
            continue
        # Inspect CSS-declared resources as part of inspecting a referenced stylesheet.
        ctype = " ".join(str(x) for x in rec.get("response_headers", "").splitlines() if x.lower().startswith("content-type:" )).lower()
        if "css" in ctype or urlsplit(url).path.lower().endswith(".css"):
            css = body.decode("utf-8", errors="replace")
            css_urls = re.findall(r"url\((?:\s*['\"]?)(.*?)(?:['\"]?\s*)\)", css, flags=re.I)
            css_urls += re.findall(r"@import\s+(?:url\()?\s*['\"]([^'\"]+)", css, flags=re.I)
            for value in css_urls:
                value = value.strip()
                if not value or value.startswith("data:"):
                    continue
                resolved, _ = urldefrag(urljoin(url, value))
                report["homepage_referenced_resources"].append({"tag": "css", "attribute": "url", "url": resolved})
                if in_application(resolved) and resolved not in seen:
                    scheduled.append((resolved, "css_referenced_resource"))
                    seen.add(resolved)
                elif not in_application(resolved):
                    report["limitations"].append("External CSS resource recorded but not fetched: " + resolved)
    print(json.dumps(report, ensure_ascii=False))

if __name__ == "__main__":
    main()

