import base64
import hashlib
import json
import sys
from html.parser import HTMLParser
from urllib.error import HTTPError, URLError
from urllib.parse import urljoin, urlsplit, urlunsplit
from urllib.request import Request, urlopen

BASE = "http://192.168.2.0/"
USER_AGENT = "RouteEvidenceCapture/1.0"
TIMEOUT_SECONDS = 30


class PageInventory(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.forms = []
        self.resources = []
        self._form = None

    @staticmethod
    def attrs_dict(attrs):
        return {str(k).lower(): v for k, v in attrs}

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        a = self.attrs_dict(attrs)
        if tag == "a":
            self.links.append({"tag": tag, "attributes": a})
        if tag == "form":
            self._form = {"attributes": a, "controls": []}
            self.forms.append(self._form)
        elif self._form is not None and tag in ("input", "button", "select", "textarea"):
            self._form["controls"].append({"tag": tag, "attributes": a})

        candidates = []
        if tag in ("link", "script", "img", "iframe", "frame", "source", "audio", "video", "track", "embed"):
            if a.get("href"):
                candidates.append(("href", a["href"]))
            if a.get("src"):
                candidates.append(("src", a["src"]))
        if tag == "video" and a.get("poster"):
            candidates.append(("poster", a["poster"]))
        if tag == "object" and a.get("data"):
            candidates.append(("data", a["data"]))
        if a.get("srcset"):
            for item in a["srcset"].split(","):
                value = item.strip().split()
                if value:
                    candidates.append(("srcset", value[0]))
        for attribute, value in candidates:
            self.resources.append({"tag": tag, "attribute": attribute, "value": value})

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._form = None


def request_url(value, base):
    resolved = urljoin(base, value)
    parts = urlsplit(resolved)
    return urlunsplit((parts.scheme, parts.netloc, parts.path or "/", parts.query, ""))


def same_origin(url, origin):
    a, b = urlsplit(url), urlsplit(origin)
    def effective_port(p):
        return p.port or (443 if p.scheme.lower() == "https" else 80)
    return (a.scheme.lower() in ("http", "https") and
            a.scheme.lower() == b.scheme.lower() and
            (a.hostname or "").lower() == (b.hostname or "").lower() and
            effective_port(a) == effective_port(b))


def is_php_route(url):
    return urlsplit(url).path.lower().endswith(".php")


def fetch(url, purpose):
    headers = {"User-Agent": USER_AGENT, "Accept": "*/*"}
    req = Request(url, headers=headers, method="GET")
    entry = {
        "purpose": purpose,
        "request": {"method": "GET", "url": url, "headers": headers},
    }
    response = None
    try:
        try:
            response = urlopen(req, timeout=TIMEOUT_SECONDS)
        except HTTPError as exc:
            # HTTP error responses still have useful status, headers, and body evidence.
            response = exc
        body = response.read()
        entry["response"] = {
            "status": response.code,
            "reason": getattr(response, "reason", ""),
            "headers": list(response.headers.items()),
            "final_url": response.geturl(),
            "body_length_bytes": len(body),
            "body_sha256": hashlib.sha256(body).hexdigest(),
            "body_base64": base64.b64encode(body).decode("ascii"),
        }
        content_type = response.headers.get("Content-Type", "")
        entry["response"]["content_type"] = content_type
        if content_type.lower().startswith(("text/", "application/xhtml+xml", "application/json", "application/javascript", "application/xml")):
            charset = "utf-8"
            for part in content_type.split(";")[1:]:
                key, sep, value = part.strip().partition("=")
                if sep and key.lower() == "charset":
                    charset = value.strip(' \"\'')
                    break
            try:
                entry["response"]["body_text"] = body.decode(charset)
                entry["response"]["text_decode_error"] = None
            except (LookupError, UnicodeDecodeError) as exc:
                entry["response"]["body_text"] = None
                entry["response"]["text_decode_error"] = str(exc)
        return entry, body, content_type
    except (URLError, OSError, TimeoutError, ValueError) as exc:
        entry["error"] = {"type": type(exc).__name__, "message": str(exc)}
        return entry, None, ""
    finally:
        if response is not None:
            try:
                response.close()
            except Exception:
                pass


def main():
    origin = urlsplit(BASE)
    output = {
        "target": BASE,
        "method": "GET",
        "scope": "Homepage, its advertised same-origin PHP routes, and directly referenced same-origin resources only.",
        "form_submission": "Forms are inspected but not submitted.",
        "requests": [],
        "homepage_inventory": None,
        "coverage": {"complete": False, "notes": []},
    }

    home_entry, home_body, home_type = fetch(BASE, "homepage")
    output["requests"].append(home_entry)
    if home_body is None:
        output["coverage"]["notes"].append("Homepage response body could not be obtained; advertised routes and resources could not be inventoried.")
        print(json.dumps(output, ensure_ascii=False))
        return

    inventory = PageInventory()
    try:
        charset = "utf-8"
        for part in home_type.split(";")[1:]:
            key, sep, value = part.strip().partition("=")
            if sep and key.lower() == "charset":
                charset = value.strip(' \"\'')
                break
        html = home_body.decode(charset, errors="replace")
        inventory.feed(html)
        inventory.close()
    except Exception as exc:
        output["coverage"]["notes"].append("Homepage HTML parsing failed: " + str(exc))
        print(json.dumps(output, ensure_ascii=False))
        return

    links = []
    forms = []
    advertised_routes = []
    referenced_resources = []

    for item in inventory.links:
        attrs = item["attributes"]
        href = attrs.get("href")
        resolved = request_url(href, BASE) if href else None
        record = {"attributes": attrs, "resolved_url": resolved}
        links.append(record)
        if resolved and same_origin(resolved, BASE) and is_php_route(resolved):
            advertised_routes.append({"source": "anchor", "original_value": href, "url": resolved})

    for item in inventory.forms:
        attrs = item["attributes"]
        action = attrs.get("action", BASE)
        resolved = request_url(action, BASE)
        forms.append({"attributes": attrs, "resolved_action": resolved, "controls": item["controls"], "submitted": False})
        if same_origin(resolved, BASE) and is_php_route(resolved):
            advertised_routes.append({"source": "form_action", "original_value": action, "url": resolved, "declared_method": attrs.get("method", "get").lower()})

    for item in inventory.resources:
        resolved = request_url(item["value"], BASE)
        record = {"tag": item["tag"], "attribute": item["attribute"], "original_value": item["value"], "url": resolved}
        referenced_resources.append(record)

    output["homepage_inventory"] = {
        "links": links,
        "forms": forms,
        "referenced_resources": referenced_resources,
        "advertised_same_origin_php_routes": advertised_routes,
    }

    # Parent evidence states these advertised PHP routes were not recovered or checked.
    # Deduplicate identical URLs while preserving every advertised occurrence above.
    scheduled = {BASE}
    for route in advertised_routes:
        url = route["url"]
        if url not in scheduled:
            scheduled.add(url)
            entry, _, _ = fetch(url, "advertised_php_route")
            output["requests"].append(entry)
    for resource in referenced_resources:
        url = resource["url"]
        if not same_origin(url, BASE):
            output["coverage"]["notes"].append("Skipped cross-origin referenced resource: " + url)
            continue
        if is_php_route(url):
            # It is already captured as an advertised route when advertised by a link/action;
            # do not issue a duplicate request if it was already scheduled.
            if url in scheduled:
                continue
        if url not in scheduled:
            scheduled.add(url)
            entry, _, _ = fetch(url, "referenced_resource")
            output["requests"].append(entry)

    failed = [r for r in output["requests"] if "error" in r]
    if failed:
        output["coverage"]["notes"].append(str(len(failed)) + " request(s) did not yield a complete response body.")
    output["coverage"]["complete"] = not failed
    output["coverage"]["requests_attempted"] = len(output["requests"])
    output["coverage"]["same_origin_php_routes_found"] = len(advertised_routes)
    output["coverage"]["same_origin_php_routes_requested"] = sum(1 for r in output["requests"] if r.get("purpose") == "advertised_php_route")
    print(json.dumps(output, ensure_ascii=False))


if __name__ == "__main__":
    main()

