import base64
import gzip
import http.client
import json
import re
import sys
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urldefrag

BASE = "http://192.168.2.0/"
HOST = "192.168.2.0"
PORT = 80
TIMEOUT = 20

class PageInventory(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.forms = []
        self.resources = []
        self._form = None

    def handle_starttag(self, tag, attrs):
        self._tag(tag, attrs)

    def handle_startendtag(self, tag, attrs):
        self._tag(tag, attrs)

    def _tag(self, tag, attrs):
        a = {str(k).lower(): (v or "") for k, v in attrs}
        if tag.lower() == "a" and a.get("href"):
            self.links.append({"href": a["href"], "text": ""})
        if tag.lower() == "form":
            self._form = {"action": a.get("action", ""), "method": a.get("method", "get").upper(),
                          "enctype": a.get("enctype", "application/x-www-form-urlencoded"), "fields": []}
            self.forms.append(self._form)
        if self._form is not None and tag.lower() in ("input", "select", "textarea", "button"):
            self._form["fields"].append({"tag": tag.lower(), "name": a.get("name", ""),
                                         "type": a.get("type", "")})
        for key in ("src", "poster", "data"):
            if a.get(key):
                self.resources.append({"url": a[key], "tag": tag.lower(), "attribute": key})
        if tag.lower() == "link" and a.get("href"):
            rel = a.get("rel", "").lower().split()
            if rel:
                self.resources.append({"url": a["href"], "tag": "link", "attribute": "href", "rel": rel})
        if tag.lower() == "a" and self.links:
            self.links[-1]["text"] = ""

    def handle_data(self, data):
        if self._form is not None:
            return
        # Anchor text is not needed to decide which advertised route to request.

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._form = None

def normalized_url(raw, base):
    absolute = urldefrag(urljoin(base, raw))[0]
    p = urlsplit(absolute)
    if p.scheme.lower() != "http" or (p.hostname or "").lower() != HOST or p.port not in (None, PORT):
        return None
    path = p.path or "/"
    target = path + (("?" + p.query) if p.query else "")
    return {"url": absolute, "target": target}

def request_record(target):
    record = {
        "request": {"method": "GET", "host": HOST, "port": PORT, "target": target,
                    "headers": [["Host", HOST], ["User-Agent", "route-recapture/1.0"],
                                ["Accept", "*/*"], ["Connection", "close"]],
                    "body": ""}
    }
    conn = http.client.HTTPConnection(HOST, PORT, timeout=TIMEOUT)
    try:
        conn.request("GET", target, headers={"Host": HOST, "User-Agent": "route-recapture/1.0",
                                             "Accept": "*/*", "Connection": "close"})
        response = conn.getresponse()
        body = response.read()
        headers = response.getheaders()
        record["response"] = {
            "status": response.status,
            "reason": response.reason,
            "headers": [[str(k), str(v)] for k, v in headers],
            "body_length_bytes": len(body),
            "body_base64": base64.b64encode(body).decode("ascii"),
            "body_text": None,
            "body_text_encoding": None,
            "limitations": []
        }
        content_type = next((v for k, v in headers if k.lower() == "content-type"), "")
        charset_match = re.search(r"charset\s*=\s*[\"']?([^;\"' ]+)", content_type, re.I)
        charset = charset_match.group(1) if charset_match else "utf-8"
        text_bytes = body
        encoding = next((v for k, v in headers if k.lower() == "content-encoding"), "").lower()
        if encoding == "gzip":
            try:
                text_bytes = gzip.decompress(body)
                record["response"]["body_text_decoded_content_encoding"] = "gzip"
            except Exception as exc:
                record["response"]["limitations"].append("gzip text decoding failed: " + repr(exc))
                text_bytes = None
        elif encoding and encoding != "identity":
            record["response"]["limitations"].append("text decoding not attempted for Content-Encoding " + encoding)
            text_bytes = None
        if text_bytes is not None:
            try:
                record["response"]["body_text"] = text_bytes.decode(charset, errors="strict")
                record["response"]["body_text_encoding"] = charset
            except Exception as exc:
                record["response"]["limitations"].append("text decoding failed; full body bytes remain in body_base64: " + repr(exc))
        return record, body, content_type
    except Exception as exc:
        record["failure"] = {"type": type(exc).__name__, "message": str(exc),
                             "limitation": "No complete HTTP response was obtained; response status, headers, and body are unavailable."}
        return record, None, ""
    finally:
        conn.close()

def parse_html(body, content_type):
    if body is None:
        return None, "Homepage body unavailable; inventory could not be parsed."
    if "html" not in content_type.lower() and not body.lstrip().lower().startswith((b"<!doctype html", b"<html")):
        return None, "Homepage response was not identified as HTML; link/form/resource inventory was not parsed."
    charset_match = re.search(r"charset\s*=\s*[\"']?([^;\"' ]+)", content_type, re.I)
    charset = charset_match.group(1) if charset_match else "utf-8"
    try:
        text = body.decode(charset, errors="strict")
        parser = PageInventory()
        parser.feed(text)
        parser.close()
        return parser, None
    except Exception as exc:
        return None, "HTML decoding/parsing failed: " + repr(exc)

def main():
    report = {
        "target": BASE,
        "scope": "Homepage, same-origin PHP routes advertised as links on that homepage, and same-origin referenced resources. Forms are inventoried but never submitted or fetched as actions; unadvertised paths are not requested.",
        "timeout_seconds_per_request": TIMEOUT,
        "requests": [],
        "homepage_inventory": None,
        "coverage": {"complete": False, "limitations": []}
    }
    homepage_url = normalized_url(BASE, BASE)
    first, body, content_type = request_record(homepage_url["target"])
    first["purpose"] = "homepage"
    report["requests"].append(first)
    parser, parse_error = parse_html(body, content_type)
    if parse_error:
        report["coverage"]["limitations"].append(parse_error)
        report["homepage_inventory"] = {"links": [], "forms": [], "same_origin_referenced_resources": [], "parse_status": "not_parsed"}
        print(json.dumps(report, ensure_ascii=False))
        return

    route_candidates = []
    resource_candidates = []
    inventory_links = []
    for link in parser.links:
        resolved = normalized_url(link["href"], BASE)
        item = {"href": link["href"], "resolved_same_origin_url": resolved["url"] if resolved else None,
                "text": link.get("text", "")}
        inventory_links.append(item)
        if resolved and urlsplit(resolved["url"]).path.lower().endswith(".php"):
            route_candidates.append(resolved)
    for resource in parser.resources:
        resolved = normalized_url(resource["url"], BASE)
        item = dict(resource)
        item["resolved_same_origin_url"] = resolved["url"] if resolved else None
        resource_candidates.append(item)
        if resolved:
            resource["_resolved"] = resolved

    report["homepage_inventory"] = {
        "links": inventory_links,
        "forms": parser.forms,
        "same_origin_referenced_resources": [{k: v for k, v in item.items() if not k.startswith("_")} for item in resource_candidates],
        "parse_status": "parsed",
        "form_submission": "none"
    }
    seen = {homepage_url["target"]}
    for kind, candidates in (("advertised_php_route", route_candidates), ("referenced_resource", [r["_resolved"] for r in resource_candidates if "_resolved" in r])):
        for candidate in candidates:
            target = candidate["target"]
            if target in seen:
                continue
            seen.add(target)
            rec, _, _ = request_record(target)
            rec["purpose"] = kind
            rec["url"] = candidate["url"]
            report["requests"].append(rec)
            if "failure" in rec:
                report["coverage"]["limitations"].append(kind + " request failed for " + candidate["url"] + ": " + rec["failure"]["message"])
    report["coverage"]["complete"] = not report["coverage"]["limitations"] and all("failure" not in r for r in report["requests"])
    print(json.dumps(report, ensure_ascii=False))

if __name__ == "__main__":
    main()

