#!/usr/bin/env python3
import base64
import hashlib
import http.client
import json
import os
import re
import sys
import time
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urldefrag

BASE = "http://192.168.2.0/"
USER_AGENT = "route-capture/2.0"
OUTPUT_DIR = "/tmp/advertised_route_capture"

class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.forms = []
        self.resources = []

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == "a" and a.get("href") is not None:
            self.links.append({"tag": tag, "href": a.get("href"), "text": ""})
        if tag == "form":
            self.forms.append({"action": a.get("action", ""), "method": a.get("method", "get"), "attributes": attrs})
        if tag == "link" and a.get("href") is not None:
            self.resources.append({"tag": tag, "attribute": "href", "url": a["href"], "rel": a.get("rel", "")})
        elif tag in ("script", "img", "iframe", "audio", "video", "source", "track", "embed"):
            attr = "src"
            if tag == "video" and a.get("poster"):
                self.resources.append({"tag": tag, "attribute": "poster", "url": a["poster"]})
            if a.get(attr) is not None:
                self.resources.append({"tag": tag, "attribute": attr, "url": a[attr]})

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def handle_data(self, data):
        if self.links:
            self.links[-1]["text"] += data


def origin(url):
    p = urlsplit(url)
    port = p.port or (443 if p.scheme.lower() == "https" else 80)
    return p.scheme.lower(), (p.hostname or "").lower(), port


def same_origin(url):
    try:
        return origin(url) == origin(BASE) and urlsplit(url).scheme.lower() in ("http", "https")
    except ValueError:
        return False


def request_record(url, sequence):
    url, _fragment = urldefrag(url)
    p = urlsplit(url)
    target = p.path or "/"
    if p.query:
        target += "?" + p.query
    port = p.port or (443 if p.scheme.lower() == "https" else 80)
    headers = [
        ["Host", p.netloc],
        ["User-Agent", USER_AGENT],
        ["Accept", "text/html,application/xhtml+xml,text/css,application/javascript,*/*;q=0.8"],
        ["Accept-Encoding", "identity"],
        ["Connection", "close"],
    ]
    req = {"method": "GET", "url": url, "request_target": target, "headers": headers}
    record = {"record_type": "http_exchange", "sequence": sequence, "request": req}
    conn = None
    body = b""
    try:
        cls = http.client.HTTPSConnection if p.scheme.lower() == "https" else http.client.HTTPConnection
        conn = cls(p.hostname, port)
        conn.putrequest("GET", target, skip_host=True, skip_accept_encoding=True)
        for key, value in headers:
            conn.putheader(key, value)
        conn.endheaders()
        response = conn.getresponse()
        try:
            body = response.read()
            read_error = ""
        except Exception as exc:
            read_error = "%s: %s" % (type(exc).__name__, exc)
        response_headers = [[k, v] for k, v in response.getheaders()]
        declared = response.getheader("Content-Length")
        transfer = {
            "body_bytes_read": len(body),
            "content_length_header": declared,
            "content_encoding": response.getheader("Content-Encoding"),
            "transfer_encoding": response.getheader("Transfer-Encoding"),
            "read_error": read_error,
            "complete_read": not bool(read_error) and (declared is None or not declared.isdigit() or int(declared) == len(body)),
            "redirect_followed": False,
        }
        resp = {
            "status": response.status,
            "reason": response.reason,
            "headers": response_headers,
            "body_length_bytes": len(body),
            "body_sha256": hashlib.sha256(body).hexdigest(),
            "body_base64": base64.b64encode(body).decode("ascii"),
            "transfer": transfer,
        }
        charset = "utf-8"
        ctype = response.getheader("Content-Type", "") or ""
        match = re.search(r"charset\s*=\s*['\"]?([^;\s'\"]+)", ctype, re.I)
        if match:
            charset = match.group(1)
        try:
            resp["body_text"] = body.decode(charset)
            resp["body_text_decode_error"] = False
        except (LookupError, UnicodeDecodeError) as exc:
            resp["body_text"] = body.decode(charset if charset.lower() in ("utf-8", "ascii", "latin-1", "iso-8859-1") else "utf-8", errors="replace")
            resp["body_text_decode_error"] = "%s: %s" % (type(exc).__name__, exc)
        record["response"] = resp
        return record, body, ctype
    except Exception as exc:
        record["response"] = None
        record["request_error"] = {"type": type(exc).__name__, "message": str(exc)}
        record["limitations"] = ["No complete HTTP response was captured for this request."]
        return record, body, ""
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def html_inventory(body, content_type):
    parser = PageParser()
    try:
        parser.feed(body.decode("utf-8", errors="replace"))
        parser.close()
        return {"parse_status": "parsed", "links": parser.links, "forms": parser.forms, "resources": parser.resources, "parse_note": "HTML decoded as UTF-8 with replacement for invalid byte sequences."}
    except Exception as exc:
        return {"parse_status": "failed", "links": [], "forms": [], "resources": [], "parse_note": "%s: %s" % (type(exc).__name__, exc)}


def css_references(text):
    found = []
    # @import url(...) and quoted @import forms.
    for m in re.finditer(r"@import\s+(?:url\(\s*(['\"]?)(.*?)\1\s*\)|(['\"])(.*?)\3)", text, re.I):
        value = m.group(2) if m.group(2) is not None else m.group(4)
        if value:
            found.append(value.strip())
    # url(...) references; imports are deduplicated below.
    for m in re.finditer(r"url\(\s*(['\"]?)(.*?)\1\s*\)", text, re.I):
        value = m.group(2).strip()
        if value and not value.lower().startswith(("data:", "javascript:")):
            found.append(value)
    return list(dict.fromkeys(found))


def emit(record, index):
    encoded = json.dumps(record, ensure_ascii=False, separators=(",", ":"))
    path = os.path.join(OUTPUT_DIR, "record-%03d.json" % index)
    try:
        with open(path, "w", encoding="utf-8") as f:
            f.write(json.dumps(record, ensure_ascii=False, indent=2))
            f.write("\n")
        record["saved_record_path"] = path
        encoded = json.dumps(record, ensure_ascii=False, separators=(",", ":"))
    except OSError as exc:
        record.setdefault("limitations", []).append("Could not save separate record file: %s: %s" % (type(exc).__name__, exc))
        encoded = json.dumps(record, ensure_ascii=False, separators=(",", ":"))
    print(encoded, flush=True)


def main():
    try:
        os.makedirs(OUTPUT_DIR, exist_ok=True)
    except OSError as exc:
        print(json.dumps({"record_type": "setup_error", "message": "%s: %s" % (type(exc).__name__, exc)}), flush=True)
        return 1

    captures = {}
    queue = []
    queued = set()
    requested = set()
    limitations = []
    sequence = 0

    def fetch(url, kind):
        nonlocal sequence
        url, _ = urldefrag(url)
        key = url
        if key in requested:
            return captures.get(key)
        requested.add(key)
        sequence += 1
        rec, body, ctype = request_record(url, sequence)
        rec["label"] = kind
        emit(rec, sequence)
        captures[key] = {"record": rec, "body": body, "content_type": ctype}
        if rec.get("response") is None:
            limitations.append("Request did not yield a complete response: " + url)
        elif not rec["response"]["transfer"]["complete_read"]:
            limitations.append("Response transfer/read was incomplete or Content-Length did not match: " + url)
        return captures[key]

    home = fetch(BASE, "homepage")
    home_inventory = html_inventory(home["body"], home["content_type"])
    home_url = BASE
    advertised_routes = []
    for item in home_inventory["links"]:
        raw = item.get("href", "")
        absolute = urldefrag(urljoin(home_url, raw))[0]
        if same_origin(absolute) and urlsplit(absolute).path.lower().endswith(".php") and absolute.rstrip("/") != home_url.rstrip("/"):
            if absolute not in advertised_routes:
                advertised_routes.append(absolute)

    page_inventories = [(home_url, home_inventory)]
    for route in advertised_routes:
        captured = fetch(route, "advertised_php_route")
        inv = html_inventory(captured["body"], captured["content_type"])
        page_inventories.append((route, inv))

    for page_url, inv in page_inventories:
        for item in inv.get("resources", []):
            raw = item.get("url", "")
            absolute = urldefrag(urljoin(page_url, raw))[0]
            if absolute and same_origin(absolute) and absolute not in requested and absolute not in queued:
                queue.append((absolute, "referenced_same_origin_resource"))
                queued.add(absolute)

    resource_inventory = []
    while queue:
        url, kind = queue.pop(0)
        if url in requested:
            continue
        got = fetch(url, kind)
        resource_inventory.append({"url": url, "captured": bool(got and got["record"].get("response") is not None), "status": got["record"].get("response", {}).get("status") if got and got["record"].get("response") else None})
        if got and got["record"].get("response") is not None and "css" in (got["content_type"] or "").lower():
            try:
                text = got["body"].decode("utf-8", errors="replace")
                for ref in css_references(text):
                    absolute = urldefrag(urljoin(url, ref))[0]
                    if same_origin(absolute) and absolute not in requested and absolute not in queued:
                        queue.append((absolute, "css_referenced_same_origin_resource"))
                        queued.add(absolute)
            except Exception as exc:
                limitations.append("CSS reference parsing failed for %s: %s: %s" % (url, type(exc).__name__, exc))

    summary = {
        "record_type": "capture_summary",
        "target_homepage": BASE,
        "homepage_inventory": home_inventory,
        "advertised_same_origin_php_routes": advertised_routes,
        "route_page_inventories": [{"url": url, **inv} for url, inv in page_inventories[1:]],
        "same_origin_resource_requests": resource_inventory,
        "forms_inventoried_not_submitted": True,
        "forms_submitted": 0,
        "actual_request_count": len(requested),
        "individual_response_records": [os.path.join(OUTPUT_DIR, "record-%03d.json" % i) for i in range(1, sequence + 1)],
        "limitations": list(dict.fromkeys(limitations)),
        "coverage_note": "Requested the homepage, its advertised same-origin PHP links (excluding a self-link), same-origin resources referenced by the homepage and fetched PHP pages, and same-origin CSS url/import references. Did not submit forms, follow redirects, request unadvertised routes, or repeat excluded probe types. Each exchange was emitted as a separate JSON record; complete records are also saved individually when filesystem writing succeeds.",
    }
    summary_path = os.path.join(OUTPUT_DIR, "summary.json")
    try:
        with open(summary_path, "w", encoding="utf-8") as f:
            json.dump(summary, f, ensure_ascii=False, indent=2)
            f.write("\n")
        summary["saved_summary_path"] = summary_path
    except OSError as exc:
        summary["limitations"].append("Could not save summary file: %s: %s" % (type(exc).__name__, exc))
    print(json.dumps(summary, ensure_ascii=False, separators=(",", ":")), flush=True)
    return 0

if __name__ == "__main__":
    sys.exit(main())

