import base64
import hashlib
import http.client
import json
import re
import sys
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urlunsplit, parse_qsl

BASE = "http://192.168.2.0/"
ORIGIN = ("http", "192.168.2.0", 80)
REQUEST_HEADERS = [
    ["Host", "192.168.2.0"],
    ["User-Agent", "route-capture/2.0"],
    ["Accept", "text/html,application/xhtml+xml,text/css,application/javascript,*/*;q=0.8"],
    ["Accept-Encoding", "identity"],
    ["Connection", "close"],
]


def normalized_url(url):
    p = urlsplit(url)
    return urlunsplit((p.scheme, p.netloc, p.path or "/", p.query, ""))


def same_origin(url):
    p = urlsplit(url)
    port = p.port or (80 if p.scheme == "http" else 443)
    return (p.scheme, p.hostname, port) == ORIGIN


def decode_body(body, headers):
    charset = "utf-8"
    for name, value in headers:
        if name.lower() == "content-type":
            match = re.search(r"charset\s*=\s*[\"']?([^;\s\"']+)", value, re.I)
            if match:
                charset = match.group(1)
                break
    try:
        return body.decode(charset, errors="replace")
    except LookupError:
        return body.decode("utf-8", errors="replace")


class PageInventory(HTMLParser):
    def __init__(self, page_url):
        super().__init__(convert_charrefs=True)
        self.page_url = page_url
        self.links = []
        self.forms = []
        self.resources = []
        self._form = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "a" and "href" in attrs:
            href = attrs["href"]
            self.links.append({"tag": tag, "href": href, "resolved_url": urljoin(self.page_url, href)})
        if tag == "form":
            self._form = {"method": attrs.get("method", "get").lower(), "action": attrs.get("action", ""), "submitted": False}
            self.forms.append(self._form)
        candidates = []
        if tag == "link" and attrs.get("href") and "stylesheet" in attrs.get("rel", "").lower().split():
            candidates.append(("href", attrs["href"]))
        if tag in ("script", "img", "source", "video", "audio", "iframe", "embed", "input") and attrs.get("src"):
            candidates.append(("src", attrs["src"]))
        if tag == "object" and attrs.get("data"):
            candidates.append(("data", attrs["data"]))
        for attribute, value in candidates:
            self.resources.append({"tag": tag, "attribute": attribute, "url": value,
                                   "resolved_url": urljoin(self.page_url, value)})

    def handle_endtag(self, tag):
        if tag == "form":
            self._form = None


def request_record(url):
    p = urlsplit(url)
    target = urlunsplit(("", "", p.path or "/", p.query, ""))
    request = {
        "method": "GET", "url": url, "request_target": target,
        "http_version": "HTTP/1.1", "headers": REQUEST_HEADERS,
    }
    response = {"status": None, "reason": None, "headers": [], "body_length_bytes": 0,
                "body_sha256": None, "body_base64": "", "transfer_complete": False,
                "limitations": []}
    conn = http.client.HTTPConnection("192.168.2.0", 80, timeout=10)
    body = bytearray()
    try:
        conn.putrequest("GET", target, skip_host=True, skip_accept_encoding=True)
        for name, value in REQUEST_HEADERS:
            conn.putheader(name, value)
        conn.endheaders()
        res = conn.getresponse()
        response["status"] = res.status
        response["reason"] = res.reason
        response["headers"] = [[name, value] for name, value in res.getheaders()]
        while True:
            chunk = res.read(65536)
            if not chunk:
                break
            body.extend(chunk)
        response["transfer_complete"] = True
    except Exception as exc:
        response["limitations"].append("transfer incomplete: {}: {}".format(type(exc).__name__, exc))
    finally:
        conn.close()
    raw = bytes(body)
    response["body_length_bytes"] = len(raw)
    response["body_sha256"] = hashlib.sha256(raw).hexdigest()
    response["body_base64"] = base64.b64encode(raw).decode("ascii")
    if response["status"] is not None:
        lengths = [v for k, v in response["headers"] if k.lower() == "content-length"]
        if lengths:
            try:
                if int(lengths[-1]) != len(raw):
                    response["limitations"].append("received body length differs from Content-Length")
            except ValueError:
                response["limitations"].append("Content-Length header is not an integer")
    return {"record_type": "http_exchange", "request": request, "response": response}, raw


def main():
    requested = set()
    records = []
    inventory = {"homepage": BASE, "links": [], "forms": [], "resources": [],
                 "advertised_php_routes": [], "pages_parsed": [], "parse_limitations": []}
    resource_queue = []
    css_seen = set()

    def capture(url, purpose):
        url = normalized_url(url)
        if not same_origin(url) or url in requested:
            return None, None
        requested.add(url)
        record, body = request_record(url)
        record["purpose"] = purpose
        records.append(record)
        if record["response"]["status"] is None or not record["response"]["transfer_complete"]:
            return record, None
        return record, body

    home_record, home_body = capture(BASE, "homepage")
    if home_body is None:
        for rec in records:
            print(json.dumps(rec, ensure_ascii=False, separators=(",", ":")))
        print(json.dumps({"record_type": "coverage_summary", "inventory": inventory,
                          "requests_made": len(requested), "limitations": ["homepage could not be completely retrieved; route inventory unavailable"]}, separators=(",", ":")))
        return

    def parse_page(url, body):
        parser = PageInventory(url)
        try:
            parser.feed(decode_body(body, next((r["response"]["headers"] for r in records if r["request"]["url"] == url), [])))
            parser.close()
        except Exception as exc:
            inventory["parse_limitations"].append({"url": url, "error": "{}: {}".format(type(exc).__name__, exc)})
        inventory["pages_parsed"].append(url)
        inventory["links"].append({"page": url, "items": parser.links})
        inventory["forms"].append({"page": url, "items": parser.forms})
        inventory["resources"].append({"page": url, "items": parser.resources})
        return parser

    home_parser = parse_page(BASE, home_body)
    routes = []
    for link in home_parser.links:
        candidate = normalized_url(link["resolved_url"])
        if not same_origin(candidate):
            continue
        cp = urlsplit(candidate)
        query_has_php_page = any(k.lower() == "page" and v.lower().endswith(".php") for k, v in parse_qsl(cp.query, keep_blank_values=True))
        path_is_php = cp.path.lower().endswith(".php") and cp.path.lower() not in ("/index.php",)
        if (query_has_php_page or path_is_php) and candidate not in routes:
            routes.append(candidate)
    inventory["advertised_php_routes"] = routes

    pages = [(BASE, home_parser)]
    for route in routes:
        rec, body = capture(route, "advertised_php_route")
        if body is not None and rec["response"]["status"] is not None and 200 <= rec["response"]["status"] < 400:
            pages.append((route, parse_page(route, body)))

    for page_url, parser in pages:
        for item in parser.resources:
            resource = normalized_url(item["resolved_url"])
            if same_origin(resource):
                resource_queue.append(resource)

    while resource_queue:
        resource = resource_queue.pop(0)
        if resource in requested:
            continue
        rec, body = capture(resource, "same_origin_referenced_resource")
        if body is None or rec["response"]["status"] is None:
            continue
        path = urlsplit(resource).path.lower()
        content_types = [v.lower() for k, v in rec["response"]["headers"] if k.lower() == "content-type"]
        is_css = path.endswith(".css") or any("text/css" in v for v in content_types)
        if is_css and resource not in css_seen:
            css_seen.add(resource)
            text = decode_body(body, rec["response"]["headers"])
            refs = re.findall(r"@import\s+(?:url\()?\s*[\"']?([^\"')\s;]+)|url\(\s*[\"']?([^\"')]+)", text, re.I)
            found = []
            for a, b in refs:
                value = (a or b).strip()
                if not value or value.startswith(("data:", "#")):
                    continue
                absolute = normalized_url(urljoin(resource, value))
                if same_origin(absolute) and absolute not in requested and absolute not in found:
                    found.append(absolute)
            inventory["resources"].append({"page": resource, "source": "css_url_or_import", "items": [{"url": u} for u in found]})
            resource_queue.extend(found)

    for rec in records:
        print(json.dumps(rec, ensure_ascii=False, separators=(",", ":")))
    summary = {
        "record_type": "coverage_summary",
        "inventory": inventory,
        "requests_made": len(records),
        "forms_submitted": 0,
        "coverage_note": "Requested the homepage, its advertised PHP routes, and same-origin resources referenced by the homepage and retrieved route pages; retrieved same-origin CSS url()/@import references. No forms were submitted, no unadvertised paths were requested, and no direct-file, path-resolution, wrapper, or source-display probes were made.",
        "limitations": ["See each record's transfer_complete and limitations fields; parsing limitations are listed in inventory."]
    }
    print(json.dumps(summary, ensure_ascii=False, separators=(",", ":")))


if __name__ == "__main__":
    main()

