import base64
import hashlib
import http.client
import json
import re
import sys
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urlunsplit

BASE = "http://192.168.2.0/"
REQUEST_HEADERS = [
    ("User-Agent", "route-capture-individual/1.0"),
    ("Accept", "text/html,application/xhtml+xml,text/css,application/javascript,*/*;q=0.8"),
    ("Accept-Encoding", "identity"),
    ("Connection", "close"),
]


def emit(obj):
    print(json.dumps(obj, ensure_ascii=False, separators=(",", ":")), flush=True)


def origin(url):
    p = urlsplit(url)
    port = p.port or (80 if p.scheme == "http" else 443)
    return p.scheme.lower(), (p.hostname or "").lower(), port


def same_origin(url):
    return origin(url) == origin(BASE)


def clean_url(url):
    p = urlsplit(url)
    return urlunsplit((p.scheme, p.netloc, p.path or "/", p.query, ""))


class PageInventory(HTMLParser):
    def __init__(self, page_url):
        super().__init__(convert_charrefs=True)
        self.page_url = page_url
        self.links = []
        self.forms = []
        self.resources = []
        self._form = None
        self._anchor = None

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        tag = tag.lower()
        if tag == "a" and "href" in a:
            self._anchor = {"tag": "a", "href": a["href"], "text": ""}
            resolved = clean_url(urljoin(self.page_url, a["href"]))
            self._anchor.update({"resolved_url": resolved, "same_origin": same_origin(resolved)})
            self.links.append(self._anchor)
        if tag == "form":
            self._form = {"method": a.get("method", "get").upper(), "action": a.get("action", ""), "submitted": False}
            resolved = clean_url(urljoin(self.page_url, self._form["action"]))
            self._form.update({"resolved_action": resolved, "same_origin": same_origin(resolved)})
            self.forms.append(self._form)
        attr = None
        if tag in ("link", "a") and "href" in a:
            rel = (a.get("rel") or "").lower().split()
            if tag == "link" and any(x in rel for x in ("stylesheet", "icon", "preload", "manifest")):
                attr = "href"
        elif tag in ("script", "img", "source", "video", "audio", "iframe", "embed", "track") and "src" in a:
            attr = "src"
        if attr:
            value = a[attr]
            resolved = clean_url(urljoin(self.page_url, value))
            self.resources.append({"tag": tag, "attribute": attr, "url": value,
                                   "resolved_url": resolved, "same_origin": same_origin(resolved)})
        if tag == "source" and "srcset" in a:
            for entry in a["srcset"].split(","):
                value = entry.strip().split()
                if value:
                    resolved = clean_url(urljoin(self.page_url, value[0]))
                    self.resources.append({"tag": tag, "attribute": "srcset", "url": value[0],
                                           "resolved_url": resolved, "same_origin": same_origin(resolved)})

    def handle_endtag(self, tag):
        if tag.lower() == "a":
            self._anchor = None
        elif tag.lower() == "form":
            self._form = None

    def handle_data(self, data):
        if self._anchor is not None:
            self._anchor["text"] += data


def request(url):
    p = urlsplit(url)
    target = p.path or "/"
    if p.query:
        target += "?" + p.query
    conn = None
    status = None
    reason = ""
    response_headers = []
    body = b""
    limitations = []
    request_headers = [("Host", p.netloc)] + REQUEST_HEADERS
    try:
        if p.scheme != "http":
            raise ValueError("Only the observed HTTP origin is supported by this capture script")
        conn = http.client.HTTPConnection(p.hostname, p.port or 80, timeout=12)
        conn.putrequest("GET", target, skip_host=True, skip_accept_encoding=True)
        for name, value in request_headers:
            conn.putheader(name, value)
        conn.endheaders()
        response = conn.getresponse()
        status, reason = response.status, response.reason
        response_headers = [[k, v] for k, v in response.getheaders()]
        try:
            body = response.read()
        except http.client.IncompleteRead as exc:
            body = exc.partial or b""
            if exc.expected is not None:
                limitations.append("Incomplete response body read; expected additional bytes: %s" % exc.expected)
            else:
                limitations.append("Incomplete response body read")
        except Exception as exc:
            limitations.append("Body read error: %s: %s" % (type(exc).__name__, exc))
    except Exception as exc:
        limitations.append("Request/response error: %s: %s" % (type(exc).__name__, exc))
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    if status is not None:
        declared = next((v for k, v in response_headers if k.lower() == "content-length"), None)
        if declared and declared.isdigit() and int(declared) != len(body):
            limitations.append("Content-Length is %s, received %s bytes" % (declared, len(body)))
    content_type = next((v for k, v in response_headers if k.lower() == "content-type"), "")
    is_text = ("text/" in content_type.lower() or "json" in content_type.lower()
               or "javascript" in content_type.lower() or "xml" in content_type.lower())
    record = {
        "record_type": "http_exchange",
        "request": {"method": "GET", "url": url, "request_target": target,
                    "headers": [[k, v] for k, v in request_headers]},
        "response": {"status": status, "reason": reason, "headers": response_headers,
                     "body_length_bytes": len(body), "body_sha256": hashlib.sha256(body).hexdigest()},
        "transfer_complete": not any("Incomplete" in x or "Content-Length" in x or "Request/response error" in x for x in limitations),
        "limitations": limitations,
    }
    if is_text:
        charset_match = re.search(r"charset\s*=\s*[\"']?([^;\s\"']+)", content_type, re.I)
        charset = charset_match.group(1) if charset_match else "utf-8"
        try:
            record["response"]["body_text"] = body.decode(charset)
            record["response"]["body_encoding"] = charset
        except (LookupError, UnicodeDecodeError) as exc:
            record["response"]["body_base64"] = base64.b64encode(body).decode("ascii")
            record["limitations"].append("Body not decoded as text (%s); complete bytes are in body_base64" % exc)
    elif body:
        record["response"]["body_base64"] = base64.b64encode(body).decode("ascii")
    emit(record)
    return {"url": url, "status": status, "content_type": content_type, "body": body,
            "transfer_complete": record["transfer_complete"], "limitations": limitations}


def route_from_link(url):
    p = urlsplit(url)
    if not same_origin(url) or p.path.lower() != "/index.php":
        return False
    from urllib.parse import parse_qs
    return any(v.lower().endswith(".php") for v in parse_qs(p.query).get("page", []))


def css_references(text, css_url):
    found = []
    # CSS @import can use quoted URLs or url(...); url(...) also covers ordinary assets.
    patterns = [r"@import\s+(?:url\(\s*)?[\"']([^\"']+)[\"']", r"url\(\s*[\"']?([^\"')]+)"]
    for pattern in patterns:
        for match in re.finditer(pattern, text, re.I):
            value = match.group(1).strip()
            if value and not value.startswith(("data:", "#", "javascript:")):
                resolved = clean_url(urljoin(css_url, value))
                if same_origin(resolved):
                    found.append(resolved)
    return found


def main():
    pending_pages = [BASE]
    requested_pages = set()
    pending_resources = []
    requested_resources = set()
    inventory = {"pages": [], "resources": [], "forms_submitted": 0, "limitations": []}
    while pending_pages:
        page_url = pending_pages.pop(0)
        page_url = clean_url(page_url)
        if page_url in requested_pages:
            continue
        requested_pages.add(page_url)
        result = request(page_url)
        page_entry = {"url": page_url, "status": result["status"], "transfer_complete": result["transfer_complete"]}
        inventory["pages"].append(page_entry)
        if result["limitations"]:
            inventory["limitations"].append({"url": page_url, "limitations": result["limitations"]})
        if not result["body"]:
            page_entry.update({"parse_status": "not_parsed", "links": [], "forms": [], "resources": []})
            continue
        content_type = result["content_type"].lower()
        if "html" not in content_type and page_url == BASE:
            page_entry.update({"parse_status": "not_html", "links": [], "forms": [], "resources": []})
            continue
        try:
            text = result["body"].decode("utf-8", "replace")
            parser = PageInventory(page_url)
            parser.feed(text)
            parser.close()
            links, forms, resources = parser.links, parser.forms, parser.resources
            page_entry.update({"parse_status": "parsed", "links": links, "forms": forms, "resources": resources})
            if "\ufffd" in text:
                page_entry["parse_limitation"] = "UTF-8 replacement characters occurred during HTML parsing; response record retains full body representation"
            for link in links:
                if link["same_origin"] and route_from_link(link["resolved_url"]):
                    route = link["resolved_url"]
                    if route not in requested_pages and route not in pending_pages:
                        pending_pages.append(route)
            for resource in resources:
                if resource["same_origin"]:
                    resource_url = resource["resolved_url"]
                    if resource_url not in requested_resources and resource_url not in pending_resources:
                        pending_resources.append(resource_url)
        except Exception as exc:
            page_entry.update({"parse_status": "error", "parse_error": "%s: %s" % (type(exc).__name__, exc),
                               "links": [], "forms": [], "resources": []})
            inventory["limitations"].append({"url": page_url, "limitations": ["HTML parsing failed"]})

    while pending_resources:
        resource_url = pending_resources.pop(0)
        resource_url = clean_url(resource_url)
        if resource_url in requested_resources:
            continue
        requested_resources.add(resource_url)
        result = request(resource_url)
        entry = {"url": resource_url, "status": result["status"], "content_type": result["content_type"],
                 "transfer_complete": result["transfer_complete"]}
        inventory["resources"].append(entry)
        if result["limitations"]:
            inventory["limitations"].append({"url": resource_url, "limitations": result["limitations"]})
        if "css" in result["content_type"].lower() and result["body"]:
            css_text = result["body"].decode("utf-8", "replace")
            refs = css_references(css_text, resource_url)
            entry["same_origin_css_references"] = refs
            for ref in refs:
                if ref not in requested_resources and ref not in pending_resources:
                    pending_resources.append(ref)
    emit({"record_type": "capture_inventory", "homepage": BASE, "pages": inventory["pages"],
          "resources": inventory["resources"], "forms_submitted": 0,
          "limitations": inventory["limitations"],
          "coverage_note": "Requested the homepage, its advertised same-origin index.php?page=*.php routes, and same-origin resources referenced by fetched pages and CSS. Forms were inventoried but not submitted. No unadvertised paths or direct-file, path-resolution, wrapper, or source-display probes were made."})


if __name__ == "__main__":
    main()

