import base64
import hashlib
import json
import re
import sys
from html.parser import HTMLParser
from urllib.error import HTTPError, URLError
from urllib.parse import urldefrag, urljoin, urlsplit
from urllib.request import HTTPRedirectHandler, Request, build_opener

BASE = "http://192.168.2.0/"
TIMEOUT = 20
REQUEST_HEADERS = [
    ("User-Agent", "route-capture-records/1.0"),
    ("Accept", "text/html,application/xhtml+xml,text/css,application/javascript,*/*;q=0.8"),
    ("Accept-Encoding", "identity"),
    ("Connection", "close"),
]


def emit(record):
    print(json.dumps(record, ensure_ascii=False, separators=(",", ":")), flush=True)


def same_origin(url):
    a, b = urlsplit(BASE), urlsplit(url)
    return (a.scheme.lower(), a.hostname, a.port or 80) == (
        b.scheme.lower(), b.hostname, b.port or 80
    )


def clean_url(url):
    return urldefrag(url)[0]


class PageInventory(HTMLParser):
    RESOURCE_ATTRS = {
        "script": ("src",), "img": ("src", "srcset"),
        "source": ("src", "srcset"), "video": ("src", "poster"),
        "audio": ("src",), "track": ("src",), "iframe": ("src",),
        "embed": ("src",), "object": ("data",),
    }

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links, self.forms, self.resources = [], [], []

    def handle_starttag(self, tag, attrs):
        d = dict(attrs)
        if tag == "a" and d.get("href"):
            self.links.append({"tag": tag, "href": d["href"], "text": ""})
        if tag == "form":
            self.forms.append({"action": d.get("action", ""), "method": d.get("method", "get")})
        if tag == "link" and d.get("href"):
            rel = d.get("rel", "").lower().split()
            if any(x in rel for x in ("stylesheet", "icon", "preload", "modulepreload")):
                self.resources.append({"tag": tag, "attribute": "href", "url": d["href"], "rel": rel})
        for attr in self.RESOURCE_ATTRS.get(tag, ()):
            value = d.get(attr)
            if value:
                self.resources.append({"tag": tag, "attribute": attr, "url": value})
        if tag == "style":
            self._in_style = True

    def handle_endtag(self, tag):
        if tag == "style":
            self._in_style = False

    def handle_data(self, data):
        pass


def parse_html(body, url):
    parser = PageInventory()
    try:
        parser.feed(body.decode("utf-8", "replace"))
        parser.close()
        for item in parser.links:
            item["resolved_url"] = urljoin(url, item["href"])
            item["same_origin"] = same_origin(item["resolved_url"])
        for item in parser.resources:
            raw = item["url"]
            if item["attribute"] == "srcset":
                candidates = [part.strip().split()[0] for part in raw.split(",") if part.strip()]
            else:
                candidates = [raw]
            item["resolved_urls"] = [urljoin(url, candidate) for candidate in candidates]
            item["same_origin"] = all(same_origin(u) for u in item["resolved_urls"])
        return {
            "status": "parsed", "links": parser.links,
            "forms": parser.forms, "resources": parser.resources,
        }
    except Exception as exc:
        return {"status": "parse_error", "error": repr(exc), "links": [], "forms": [], "resources": []}


def css_references(body, url):
    text = body.decode("utf-8", "replace")
    found = []
    pattern = re.compile(r"@import\s+(?:url\(\s*)?[\"']?([^\s\"'()]+)[\"']?\s*\)?|url\(\s*[\"']?([^\"')]+)", re.I)
    for match in pattern.finditer(text):
        raw = (match.group(1) or match.group(2) or "").strip()
        if not raw or raw.startswith(("data:", "#")):
            continue
        absolute = clean_url(urljoin(url, raw))
        if same_origin(absolute):
            found.append(absolute)
    return found


class NoRedirect(HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


opener = build_opener(NoRedirect())
queue = [BASE]
queued = {clean_url(BASE)}
requested = set()
route_urls = []
records = 0

while queue:
    url = clean_url(queue.pop(0))
    if url in requested:
        continue
    requested.add(url)
    req_headers = list(REQUEST_HEADERS)
    request = Request(url, headers=dict(req_headers), method="GET")
    response = None
    error = None
    try:
        response = opener.open(request, timeout=TIMEOUT)
    except HTTPError as exc:
        response = exc
    except (URLError, OSError, TimeoutError) as exc:
        error = repr(exc)

    if response is None:
        emit({
            "record_type": "http_exchange", "request": {
                "method": "GET", "url": url, "request_target": urlsplit(url).path + (("?" + urlsplit(url).query) if urlsplit(url).query else ""),
                "headers": req_headers + [("Host", urlsplit(url).netloc)],
            },
            "response": None, "transfer_error": error,
            "limitations": ["No HTTP response was obtained; response status, headers, and body are unavailable."],
        })
        records += 1
        continue

    try:
        body = response.read()
        status = response.status
        reason = response.reason
        response_headers = list(response.headers.raw_items())
        final_url = response.geturl()
    except Exception as exc:
        body = b""
        status = getattr(response, "status", None)
        reason = getattr(response, "reason", None)
        response_headers = list(response.headers.raw_items()) if getattr(response, "headers", None) else []
        final_url = url
        error = "response read failed: " + repr(exc)
    finally:
        response.close()

    try:
        body_value = body.decode("utf-8")
        body_encoding = "utf-8"
    except UnicodeDecodeError:
        body_value = base64.b64encode(body).decode("ascii")
        body_encoding = "base64"

    content_type = ""
    for key, value in response_headers:
        if key.lower() == "content-type":
            content_type = value
    inventory = None
    if "html" in content_type.lower() or urlsplit(url).path.lower().endswith((".html", ".htm", ".php", "/")):
        inventory = parse_html(body, url)
    limitations = []
    if error:
        limitations.append(error)
    if inventory and inventory["status"] != "parsed":
        limitations.append("HTML inventory parsing did not complete successfully.")

    emit({
        "record_type": "http_exchange",
        "request": {
            "method": "GET", "url": url,
            "request_target": urlsplit(url).path + (("?" + urlsplit(url).query) if urlsplit(url).query else ""),
            "headers": req_headers + [("Host", urlsplit(url).netloc)],
        },
        "response": {
            "final_url": final_url, "status": status, "reason": reason,
            "headers": response_headers, "body_length_bytes": len(body),
            "body_sha256": hashlib.sha256(body).hexdigest(),
            "body_encoding": body_encoding, "body": body_value,
            "inventory": inventory,
        },
        "limitations": limitations,
    })
    records += 1

    discovered = []
    if url == clean_url(BASE) and inventory:
        for link in inventory["links"]:
            candidate = clean_url(link["resolved_url"])
            if same_origin(candidate) and urlsplit(candidate).path.lower().endswith(".php"):
                if candidate not in route_urls:
                    route_urls.append(candidate)
                    discovered.append(candidate)
    # Only the homepage's advertised PHP links are followed as page routes.
    if url == clean_url(BASE):
        for candidate in route_urls:
            if candidate not in queued and candidate not in requested:
                queue.append(candidate)
                queued.add(candidate)
    # Fetch same-origin resources referenced by this captured page.
    if inventory:
        for item in inventory["resources"]:
            for candidate in item.get("resolved_urls", []):
                candidate = clean_url(candidate)
                if same_origin(candidate) and candidate not in queued and candidate not in requested:
                    queue.append(candidate)
                    queued.add(candidate)
    # CSS imports and url() resources are relevant same-origin references.
    if "css" in content_type.lower() or urlsplit(url).path.lower().endswith(".css"):
        for candidate in css_references(body, url):
            if candidate not in queued and candidate not in requested:
                queue.append(candidate)
                queued.add(candidate)

    emit({
        "record_type": "page_inventory", "page_url": url,
        "inventory_status": inventory["status"] if inventory else "not_html",
        "links": inventory["links"] if inventory else [],
        "forms": inventory["forms"] if inventory else [],
        "resources": inventory["resources"] if inventory else [],
        "new_homepage_php_routes": discovered,
    })

emit({
    "record_type": "coverage_summary", "homepage": BASE,
    "homepage_advertised_php_routes": route_urls,
    "requested_urls": sorted(requested), "request_record_count": records,
    "forms_submitted": 0,
    "coverage_note": "Requested the homepage, its same-origin advertised PHP routes, and same-origin resources referenced by captured pages and CSS. Forms were inventoried but not submitted. No unadvertised PHP paths or excluded direct-file, path-resolution, wrapper, or source-display probes were made.",
})

