import json
from pathlib import Path

CAPTURE_DIR = Path("/root/scripts")
CAPTURE_SCRIPT = CAPTURE_DIR / "capture_route_records.py"
REQUESTED_URLS = [
    "http://192.168.2.0/",
    "http://192.168.2.0/css/style.css",
    "http://192.168.2.0/index.php",
    "http://192.168.2.0/index.php?page=page1.php",
    "http://192.168.2.0/index.php?page=page2.php",
    "http://192.168.2.0/index.php?page=page3.php",
]


def emit(value):
    print(json.dumps(value, ensure_ascii=False, separators=(",", ":")))


def records_from_file(path):
    """Read candidate saved data only; never execute candidate files."""
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        emit({"record_type": "recovery_error", "path": str(path), "error": str(exc)})
        return []

    found = []
    try:
        parsed = json.loads(text)
        values = parsed if isinstance(parsed, list) else [parsed]
        found.extend(v for v in values if isinstance(v, dict) and v.get("record_type") == "http_exchange")
    except json.JSONDecodeError:
        for line_number, line in enumerate(text.splitlines(), 1):
            try:
                value = json.loads(line)
            except json.JSONDecodeError:
                continue
            if isinstance(value, dict) and value.get("record_type") == "http_exchange":
                found.append(value)
    return found


def main():
    emit({
        "record_type": "recovery_scope",
        "checked_directory": str(CAPTURE_DIR),
        "capture_script_present": CAPTURE_SCRIPT.is_file(),
        "network_requests_made": 0,
        "capture_script_executed": False,
    })

    candidates = []
    try:
        for path in CAPTURE_DIR.iterdir():
            if path.is_file() and path != CAPTURE_SCRIPT and ("capture" in path.name.lower() or "route" in path.name.lower()):
                candidates.append(path)
    except OSError as exc:
        emit({"record_type": "recovery_error", "path": str(CAPTURE_DIR), "error": str(exc)})

    recovered = 0
    for path in sorted(candidates, key=lambda p: p.name):
        for record in records_from_file(path):
            recovered += 1
            emit({"record_type": "recovered_saved_record", "source_path": str(path), "record": record})

    if recovered == 0:
        emit({
            "record_type": "recovery_limitation",
            "detail": "No saved HTTP exchange records were found among capture/route-named files in /root/scripts. This does not establish that records are absent elsewhere. The prior stdout evidence was truncated, and no evidence-store retrieval interface or archive path was supplied to this execution.",
        })

    emit({
        "record_type": "coverage_details_from_prior_capture",
        "homepage": "http://192.168.2.0/",
        "advertised_php_routes": REQUESTED_URLS[2:],
        "requested_urls": REQUESTED_URLS,
        "reported_request_record_count": 6,
        "forms_submitted": 0,
        "coverage_note": "The prior capture reported requesting the homepage, its same-origin advertised PHP routes, and same-origin resources referenced by captured pages and CSS. It reported no unadvertised PHP paths and no excluded direct-file, path-resolution, wrapper, or source-display probes. These details do not substitute for the full individual response records.",
        "record_recovery_status": "recovered_from_local_files" if recovered else "individual_full_records_not_recovered_from_checked_location",
        "recovered_record_count": recovered,
    })


if __name__ == "__main__":
    main()

