import base64
import json
import sys
from html.parser import HTMLParser
from urllib.error import HTTPError, URLError
from urllib.parse import urljoin, urlsplit
from urllib.request import Request, urlopen

REQUEST_URL = "http://192.168.2.0/"


class DestinationParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.destinations = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        tag = tag.lower()

        if tag == "a" and attrs.get("href") is not None:
            self.destinations.append(("link", attrs["href"]))
        elif tag == "form":
            # An omitted action submits to the document URL itself.
            self.destinations.append(("form_action", attrs.get("action") or REQUEST_URL))

        if tag == "link" and attrs.get("href") is not None:
            self.destinations.append(("referenced_resource", attrs["href"]))
        for attr in ("src", "poster", "data"):
            value = attrs.get(attr)
            if value is not None and tag in {
                "audio", "embed", "iframe", "img", "input", "object",
                "script", "source", "track", "video"
            }:
                self.destinations.append(("referenced_resource", value))

        srcset = attrs.get("srcset")
        if srcset is not None and tag in {"img", "source"}:
            for candidate in srcset.split(","):
                parts = candidate.strip().split()
                if parts:
                    self.destinations.append(("referenced_resource", parts[0]))


def same_origin(url, origin):
    parsed = urlsplit(url)
    try:
        port = parsed.port
    except ValueError:
        return False
    scheme = parsed.scheme.lower()
    host = (parsed.hostname or "").lower()
    effective_port = port or (80 if scheme == "http" else 443 if scheme == "https" else None)
    return (scheme, host, effective_port) == origin


def main():
    result = {
        "request_url": REQUEST_URL,
        "method": "GET",
        "http_status": None,
        "response_body": None,
        "response_body_encoding": None,
        "response_body_bytes_base64": None,
        "same_origin_destinations": [],
        "capture_error": None,
        "capture_limitation": None,
    }

    request = Request(REQUEST_URL, method="GET", headers={"User-Agent": "homepage-evidence-capture/1.0"})
    response = None
    try:
        response = urlopen(request, timeout=20)
        status = response.status
        headers = response.headers
        body_bytes = response.read()
    except HTTPError as exc:
        status = exc.code
        headers = exc.headers
        try:
            body_bytes = exc.read()
        except Exception as read_error:
            body_bytes = None
            result["capture_limitation"] = "HTTP response received, but body read failed: " + str(read_error)
    except (URLError, TimeoutError, OSError) as exc:
        result["capture_error"] = str(exc)
        result["capture_limitation"] = "No complete HTTP response was captured."
        print(json.dumps(result, ensure_ascii=True))
        return
    finally:
        if response is not None:
            response.close()

    result["http_status"] = status
    if body_bytes is not None:
        charset = headers.get_content_charset() if headers else None
        encoding = charset or "utf-8"
        try:
            body_text = body_bytes.decode(encoding)
        except (LookupError, UnicodeDecodeError):
            encoding = "utf-8+surrogateescape"
            body_text = body_bytes.decode("utf-8", errors="surrogateescape")
        result["response_body_encoding"] = encoding
        result["response_body"] = body_text
        result["response_body_bytes_base64"] = base64.b64encode(body_bytes).decode("ascii")

        try:
            parser = DestinationParser()
            parser.feed(body_text)
            parser.close()
            parsed_request = urlsplit(REQUEST_URL)
            scheme = parsed_request.scheme.lower()
            origin = (scheme, (parsed_request.hostname or "").lower(),
                      parsed_request.port or (80 if scheme == "http" else 443))
            seen = set()
            for kind, advertised in parser.destinations:
                if not advertised:
                    continue
                resolved = urljoin(REQUEST_URL, advertised.strip())
                if same_origin(resolved, origin):
                    item = {"type": kind, "advertised_value": advertised, "url": resolved}
                    key = (kind, resolved)
                    if key not in seen:
                        result["same_origin_destinations"].append(item)
                        seen.add(key)
        except Exception as exc:
            result["capture_limitation"] = "Response body captured, but HTML route extraction failed: " + str(exc)
    elif result["capture_limitation"] is None:
        result["capture_limitation"] = "HTTP status captured, but no response body was available."

    print(json.dumps(result, ensure_ascii=True))


if __name__ == "__main__":
    main()

