import base64
import json
import urllib.error
import urllib.request

DESTINATIONS = [
    "http://192.168.2.0/css/style.css",
    "http://192.168.2.0/index.php",
    "http://192.168.2.0/index.php?page=page1.php",
    "http://192.168.2.0/index.php?page=page2.php",
    "http://192.168.2.0/index.php?page=page3.php",
]


def capture(url):
    record = {"request_url": url, "method": "GET"}
    request = urllib.request.Request(url, method="GET")
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            body = response.read()
            record.update({
                "http_status": response.status,
                "response_body": body.decode("utf-8", errors="replace"),
                "response_body_encoding": "utf-8 with replacement for invalid sequences",
                "response_body_bytes_base64": base64.b64encode(body).decode("ascii"),
                "final_url": response.geturl(),
                "capture_limitation": None,
            })
    except urllib.error.HTTPError as error:
        try:
            body = error.read()
            record.update({
                "http_status": error.code,
                "response_body": body.decode("utf-8", errors="replace"),
                "response_body_encoding": "utf-8 with replacement for invalid sequences",
                "response_body_bytes_base64": base64.b64encode(body).decode("ascii"),
                "final_url": error.geturl(),
                "capture_limitation": None,
            })
        except Exception as read_error:
            record.update({
                "http_status": error.code,
                "capture_limitation": "HTTP response received, but reading its body failed: " + str(read_error),
            })
    except Exception as error:
        record.update({
            "http_status": None,
            "response_body": None,
            "response_body_bytes_base64": None,
            "capture_limitation": type(error).__name__ + ": " + str(error),
        })
    return record


results = [capture(url) for url in DESTINATIONS]
print(json.dumps({"purpose": "Capture responses for homepage-advertised same-origin destinations only", "records": results}, ensure_ascii=False))

