import base64
import json
import urllib.error
import urllib.parse
import urllib.request
from html.parser import HTMLParser

HOME = "http://192.168.2.0/"
TIMEOUT = 20


def origin(url):
    p = urllib.parse.urlsplit(url)
    scheme = p.scheme.lower()
    host = (p.hostname or "").lower()
    try:
        port = p.port
    except ValueError:
        return None
    if port is None:
        port = 80 if scheme == "http" else 443 if scheme == "https" else None
    return (scheme, host, port)


def clean_url(url):
    p = urllib.parse.urlsplit(url)
    return urllib.parse.urlunsplit((p.scheme, p.netloc, p.path or "/", p.query, ""))


class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.refs = []
        self.forms = []
        self.base_href = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        tag = tag.lower()
        if tag == "base" and attrs.get("href") and self.base_href is None:
            self.base_href = attrs["href"]
        if tag == "form":
            self.forms.append({"action": attrs.get("action", ""),
                               "method": (attrs.get("method") or "get").upper()})
            self.refs.append(("form_action", attrs.get("action", ""),
                              (attrs.get("method") or "get").upper()))
        if attrs.get("href"):
            category = "stylesheet_or_link" if tag == "link" else "link"
            self.refs.append((category, attrs["href"], None))
        for key in ("src", "poster", "data"):
            if attrs.get(key):
                self.refs.append(("referenced_resource", attrs[key], None))
        if attrs.get("srcset"):
            for candidate in attrs["srcset"].split(","):
                value = candidate.strip().split()
                if value:
                    self.refs.append(("referenced_resource", value[0], None))

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


opener = urllib.request.build_opener(NoRedirect())
records = []


def capture(url, sources):
    record = {
        "request_url": url,
        "sources": sources,
        "status": None,
        "response_content": None,
        "response_content_base64": None,
        "response_bytes": None,
        "limitation": None,
    }
    req = urllib.request.Request(url, headers={"User-Agent": "route-evidence-capture/1.0"}, method="GET")
    try:
        response = opener.open(req, timeout=TIMEOUT)
        status = response.getcode()
        headers = response.headers
        body = response.read()
    except urllib.error.HTTPError as exc:
        status = exc.code
        headers = exc.headers
        try:
            body = exc.read()
        except Exception as read_exc:
            body = b""
            record["limitation"] = "HTTP response body could not be read: " + str(read_exc)
    except Exception as exc:
        record["limitation"] = type(exc).__name__ + ": " + str(exc)
        records.append(record)
        return record

    record["status"] = status
    record["response_bytes"] = len(body)
    record["response_content_base64"] = base64.b64encode(body).decode("ascii")
    charset = None
    if headers is not None:
        try:
            charset = headers.get_content_charset()
        except Exception:
            pass
    try:
        record["response_content"] = body.decode(charset or "utf-8", errors="strict")
        record["response_content_encoding"] = charset or "utf-8"
    except (LookupError, UnicodeDecodeError):
        record["response_content"] = body.decode("utf-8", errors="replace")
        record["response_content_encoding"] = "utf-8 with replacement; base64 field preserves exact bytes"
    if 300 <= status < 400:
        record["limitation"] = "Redirect was not followed; only the advertised request URL was captured."
    records.append(record)
    return record


home_record = capture(HOME, [{"kind": "homepage"}])
result = {
    "purpose": "Fresh homepage and advertised same-origin destination captures; no file-access probes.",
    "homepage_url": HOME,
    "homepage_parse_error": None,
    "homepage_links": [],
    "homepage_forms": [],
    "homepage_referenced_resources": [],
    "advertised_same_origin_destinations": [],
    "records": records,
}

if home_record["response_content_base64"] is not None:
    try:
        parser = PageParser()
        parser.feed(home_record["response_content"] or "")
        parser.close()
        result["homepage_forms"] = parser.forms
        resolution_base = urllib.parse.urljoin(HOME, parser.base_href) if parser.base_href else HOME
        pending = {}
        home_origin = origin(HOME)
        for kind, ref, method in parser.refs:
            if not ref or ref.strip().startswith("#"):
                continue
            absolute = clean_url(urllib.parse.urljoin(resolution_base, ref.strip()))
            parsed = urllib.parse.urlsplit(absolute)
            if parsed.scheme.lower() not in ("http", "https") or origin(absolute) != home_origin:
                continue
            source = {"kind": kind, "reference": ref}
            if method:
                source["form_method"] = method
            if kind == "form_action" and method != "GET":
                result["advertised_same_origin_destinations"].append({
                    "url": absolute,
                    "sources": [source],
                    "capture_limitation": "Form action uses method %s; the form was not submitted." % method,
                })
                continue
            if absolute not in pending:
                pending[absolute] = []
            pending[absolute].append(source)
            if kind == "link":
                result["homepage_links"].append({"url": absolute, "reference": ref})
            elif kind == "stylesheet_or_link":
                result["homepage_referenced_resources"].append({"url": absolute, "reference": ref})
            elif kind == "referenced_resource":
                result["homepage_referenced_resources"].append({"url": absolute, "reference": ref})

        for url, sources in pending.items():
            result["advertised_same_origin_destinations"].append({"url": url, "sources": sources})
            capture(url, sources)
    except Exception as exc:
        result["homepage_parse_error"] = type(exc).__name__ + ": " + str(exc)

print(json.dumps(result, ensure_ascii=False, separators=(",", ":")))

