import base64
import json
import re
import urllib.error
import urllib.parse
import urllib.request
from html.parser import HTMLParser

HOME_URL = "http://192.168.2.0/"
TIMEOUT_SECONDS = 20


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


class AdvertisedURLs(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.urls = []
        self.inline_css = []

    def handle_starttag(self, tag, attrs):
        self._collect(tag, attrs)

    def handle_startendtag(self, tag, attrs):
        self._collect(tag, attrs)

    def _collect(self, tag, attrs):
        for name, value in attrs:
            if value is None:
                continue
            name = name.lower()
            if name in ("href", "src", "action", "poster", "data"):
                self.urls.append(value.strip())
            elif name == "srcset":
                for item in value.split(","):
                    candidate = item.strip().split()
                    if candidate:
                        self.urls.append(candidate[0])
            elif name == "style":
                self.inline_css.append(value)

    def handle_data(self, data):
        # Inline style blocks may advertise additional resources.
        self.inline_css.append(data)


def origin(url):
    parts = urllib.parse.urlsplit(url)
    if parts.scheme.lower() not in ("http", "https") or not parts.hostname:
        return None
    port = parts.port
    if port is None:
        port = 80 if parts.scheme.lower() == "http" else 443
    return parts.scheme.lower(), parts.hostname.lower(), port


def css_urls(css):
    found = []
    for match in re.finditer(r"url\(\s*(['\"]?)(.*?)\1\s*\)|@import\s+(['\"])(.*?)\3", css, re.I | re.S):
        value = match.group(2) if match.group(2) is not None else match.group(4)
        value = value.strip()
        if value:
            found.append(value)
    return found


def decode_body(data, headers):
    charset = None
    if headers is not None:
        try:
            charset = headers.get_content_charset()
        except Exception:
            pass
    if not charset:
        charset = "utf-8"
    try:
        return data.decode(charset, errors="surrogateescape"), charset
    except (LookupError, UnicodeError):
        return data.decode("utf-8", errors="surrogateescape"), "utf-8-surrogateescape"


def fetch(url):
    request = urllib.request.Request(url, method="GET", headers={"User-Agent": "route-evidence-capture/1.0"})
    try:
        with urllib.request.build_opener(NoRedirect).open(request, timeout=TIMEOUT_SECONDS) as response:
            status = response.getcode()
            body = response.read()
            headers = response.headers
            error = None
    except urllib.error.HTTPError as exc:
        # Includes redirect responses; do not follow their Location target.
        status = exc.code
        try:
            body = exc.read()
        except Exception:
            body = b""
        headers = exc.headers
        error = None
    except Exception as exc:
        status = None
        body = b""
        headers = None
        error = f"{type(exc).__name__}: {exc}"

    body_text, text_encoding = decode_body(body, headers)
    record = {
        "request_url": url,
        "http_status": status,
        "response_body": body_text,
        "response_body_base64": base64.b64encode(body).decode("ascii"),
        "body_text_encoding": text_encoding,
    }
    if error is not None:
        record["limitation"] = error
    return record, headers


def advertised_destinations(body_text, base_url):
    parser = AdvertisedURLs()
    try:
        parser.feed(body_text)
        parser.close()
    except Exception:
        pass

    candidates = list(parser.urls)
    for css in parser.inline_css:
        candidates.extend(css_urls(css))

    base_origin = origin(base_url)
    destinations = []
    seen = {base_url}
    for value in candidates:
        value = value.strip()
        if not value or value.startswith("#"):
            continue
        absolute = urllib.parse.urljoin(base_url, value)
        parts = urllib.parse.urlsplit(absolute)
        if parts.scheme.lower() not in ("http", "https"):
            continue
        # Fragments are not sent in HTTP requests.
        request_url = urllib.parse.urlunsplit((parts.scheme, parts.netloc, parts.path or "/", parts.query, ""))
        if origin(request_url) != base_origin or request_url in seen:
            continue
        seen.add(request_url)
        destinations.append(request_url)
    return destinations


records = []
home_record, _ = fetch(HOME_URL)
records.append(home_record)

if home_record["http_status"] is not None:
    destinations = advertised_destinations(home_record["response_body"], HOME_URL)
    for destination in destinations:
        record, _ = fetch(destination)
        records.append(record)

for record in records:
    print(json.dumps(record, ensure_ascii=True, separators=(",", ":")))

