import json
import re
import sys

TARGET = "192.168.2.0"


def main():
    try:
        import framework_evidence
    except Exception as exc:
        print(json.dumps({
            "target": TARGET,
            "status": "inconclusive",
            "error": "Could not import the supplied framework_evidence helper: " + repr(exc),
            "coverage": "No service-identification or HTTP request was performed."
        }))
        return

    try:
        envelope = framework_evidence.run_tool(
            ["nmap", "-sV", "-p-", "--open", "-T4", TARGET]
        )
    except Exception as exc:
        print(json.dumps({
            "target": TARGET,
            "status": "inconclusive",
            "error": "Service-identification tool invocation failed: " + repr(exc),
            "coverage": "Only the known candidate was intended to be examined; no HTTP request was performed."
        }))
        return

    # Retain the original tool envelope, including its raw streams and any parser output.
    try:
        envelope_text = json.dumps(envelope, ensure_ascii=False, default=repr)
    except Exception:
        envelope_text = repr(envelope)

    stdout = ""
    if isinstance(envelope, dict):
        stdout = str(envelope.get("stdout", "") or "")
        if not stdout and isinstance(envelope.get("tool_runs"), list):
            stdout = "\n".join(
                str(run.get("stdout", ""))
                for run in envelope["tool_runs"] if isinstance(run, dict)
            )

    # Parse only open TCP service lines from the raw Nmap text. Do not infer a
    # service from a port number alone.
    open_services = []
    for line in stdout.splitlines():
        match = re.match(r"^\s*(\d+)/tcp\s+open\s+(\S+)(?:\s+(.*))?$", line)
        if match:
            open_services.append({
                "port": int(match.group(1)),
                "service": match.group(2).lower(),
                "details": (match.group(3) or "").strip(),
                "raw_line": line.strip()
            })

    import http.client
    import ssl

    requests = []
    origins = []
    for service in open_services:
        name = service["service"]
        details = service["details"].lower()
        is_https = ("https" in name or "ssl" in name or "https" in details
                    or "ssl/http" in details)
        is_http = ("http" in name or "http" in details)
        if not (is_http or is_https):
            continue

        schemes = ["https"] if is_https else ["http"]
        for scheme in schemes:
            origin = "%s://%s:%d" % (scheme, TARGET, service["port"])
            record = {"origin": origin, "method": "GET", "path": "/"}
            try:
                if scheme == "https":
                    # A lab endpoint may use a self-signed certificate. Record that
                    # certificate verification was disabled for this discovery request.
                    context = ssl._create_unverified_context()
                    connection = http.client.HTTPSConnection(
                        TARGET, service["port"], timeout=5, context=context
                    )
                    record["tls_certificate_verification"] = "disabled"
                else:
                    connection = http.client.HTTPConnection(
                        TARGET, service["port"], timeout=5
                    )
                connection.request("GET", "/", headers={"Host": TARGET, "Connection": "close"})
                response = connection.getresponse()
                record["status_code"] = response.status
                record["reason"] = response.reason
                record["headers"] = {
                    key: value for key, value in response.getheaders()
                    if key.lower() in ("server", "location", "content-type")
                }
                # Read a small amount only to complete/observe the response; no file paths
                # or advertised resources are requested here.
                record["body_prefix"] = response.read(512).decode("utf-8", "replace")
                connection.close()
                record["result"] = "http_response_received"
                origins.append(origin)
            except Exception as exc:
                record["result"] = "request_failed"
                record["error"] = repr(exc)
                try:
                    connection.close()
                except Exception:
                    pass
            requests.append(record)

    print(json.dumps({
        "target": TARGET,
        "nmap_tool_envelope": envelope_text,
        "open_tcp_services_parsed_from_raw_stdout": open_services,
        "root_http_requests": requests,
        "resolved_origins": origins,
        "status": "resolved" if origins else "unresolved",
        "coverage": "A single in-scope candidate was checked with Nmap TCP service identification across ports 1-65535. A GET / was attempted only on ports whose identified service text indicated HTTP(S). This does not establish that other candidates or unrecognized services are absent."
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

