import json
import re
import urllib.error
import urllib.parse
import urllib.request
import xml.etree.ElementTree as ET

ORIGIN = "http://192.168.2.0:80"
TIMEOUT = 15


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


OPENER = urllib.request.build_opener(NoRedirect())


def request(url):
    result = {"url": url, "method": "GET"}
    req = urllib.request.Request(url, method="GET", headers={"User-Agent": "metadata-check/1.0"})
    try:
        with OPENER.open(req, timeout=TIMEOUT) as response:
            raw = response.read()
            result.update({
                "status": response.status,
                "reason": response.reason,
                "headers": dict(response.headers.items()),
                "body": raw.decode("utf-8", errors="replace"),
                "body_bytes": len(raw),
            })
    except urllib.error.HTTPError as exc:
        raw = exc.read()
        result.update({
            "status": exc.code,
            "reason": exc.reason,
            "headers": dict(exc.headers.items()) if exc.headers else {},
            "body": raw.decode("utf-8", errors="replace"),
            "body_bytes": len(raw),
            "http_error": True,
        })
    except Exception as exc:
        result.update({"error": type(exc).__name__ + ": " + str(exc)})
    return result


def same_origin_url(reference, base):
    absolute = urllib.parse.urljoin(base, reference.strip())
    parsed = urllib.parse.urlsplit(absolute)
    origin = urllib.parse.urlsplit(ORIGIN)
    if parsed.scheme.lower() != origin.scheme or parsed.hostname != origin.hostname:
        return None
    try:
        port = parsed.port or (443 if parsed.scheme.lower() == "https" else 80)
        origin_port = origin.port or (443 if origin.scheme.lower() == "https" else 80)
    except ValueError:
        return None
    if port != origin_port or parsed.username or parsed.password:
        return None
    return urllib.parse.urlunsplit((parsed.scheme, parsed.netloc, parsed.path or "/", parsed.query, ""))


def robots_leads(body):
    sitemaps = []
    route_references = []
    for line in body.splitlines():
        line = line.split("#", 1)[0].strip()
        if ":" not in line:
            continue
        key, value = line.split(":", 1)
        key = key.strip().lower()
        value = value.strip()
        if key == "sitemap" and value:
            sitemaps.append(value)
        elif key in ("allow", "disallow") and value:
            route_references.append({"directive": key, "reference": value})
    return sitemaps, route_references


def sitemap_locations(body):
    locations = []
    try:
        root = ET.fromstring(body)
        for element in root.iter():
            if element.tag.rsplit("}", 1)[-1].lower() == "loc" and element.text:
                value = element.text.strip()
                if value:
                    locations.append(value)
        return locations, None
    except ET.ParseError as exc:
        # Retain a conservative fallback for plain loc tags in nonstandard XML.
        found = re.findall(r"<loc(?:\\s[^>]*)?>(.*?)</loc\\s*>", body, flags=re.I | re.S)
        return [re.sub(r"<[^>]+>", "", item).strip() for item in found], str(exc)


def is_sensitive_or_probe_path(url):
    parsed = urllib.parse.urlsplit(url)
    path = urllib.parse.unquote(parsed.path).lower()
    segments = [part for part in path.split("/") if part]
    if any(part in (".", "..") for part in segments):
        return "path contains traversal-like segments"
    if any(part == "flag.txt" for part in segments):
        return "direct flag.txt path skipped to avoid repeating a file-access probe"
    if "\\" in path:
        return "path contains a backslash"
    return None


def main():
    metadata = {}
    for name in ("robots.txt", "sitemap.xml"):
        url = ORIGIN + "/" + name
        metadata[name] = request(url)

    sitemap_references = []
    route_references = []
    robots_body = metadata["robots.txt"].get("body")
    if robots_body is not None:
        sitemap_references, route_references = robots_leads(robots_body)

    sitemap_body = metadata["sitemap.xml"].get("body")
    sitemap_locations_found = []
    sitemap_parse_error = None
    if sitemap_body is not None and metadata["sitemap.xml"].get("status", 0) < 400:
        sitemap_locations_found, sitemap_parse_error = sitemap_locations(sitemap_body)

    candidates = []
    for reference in sitemap_references:
        candidates.append({"source": "robots.txt Sitemap directive", "reference": reference})
    for item in route_references:
        candidates.append({"source": "robots.txt " + item["directive"].title() + " directive", "reference": item["reference"]})
    for reference in sitemap_locations_found:
        candidates.append({"source": "sitemap.xml loc", "reference": reference})

    inspected = []
    skipped = []
    seen = {ORIGIN + "/robots.txt", ORIGIN + "/sitemap.xml"}
    for candidate in candidates:
        url = same_origin_url(candidate["reference"], ORIGIN + "/")
        record = dict(candidate)
        if url is None:
            record["reason"] = "reference is not a valid same-origin URL"
            skipped.append(record)
            continue
        if url in seen:
            record["url"] = url
            record["reason"] = "duplicate metadata resource or route"
            skipped.append(record)
            continue
        seen.add(url)
        reason = is_sensitive_or_probe_path(url)
        if reason:
            record["url"] = url
            record["reason"] = reason
            skipped.append(record)
            continue
        response = request(url)
        response["identified_by"] = candidate["source"]
        response["metadata_reference"] = candidate["reference"]
        inspected.append(response)

    print(json.dumps({
        "origin": ORIGIN,
        "metadata_responses": metadata,
        "robots_sitemap_directives": sitemap_references,
        "robots_route_directives": route_references,
        "sitemap_locations": sitemap_locations_found,
        "sitemap_parse_error": sitemap_parse_error,
        "identified_resources_inspected": inspected,
        "identified_resources_skipped": skipped,
        "limitations": [
            "Redirects were not followed; redirect responses are recorded as received.",
            "Only same-origin resources explicitly identified by the metadata files were considered.",
            "Path patterns containing robots.txt wildcards are requested literally only if they pass the safety checks; no pattern expansion is performed."
        ]
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

