import json
import re
import sys
import xml.etree.ElementTree as ET

TARGET = "192.168.2.0"


def as_object(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return value
    return value


def find_xml(value):
    if isinstance(value, str):
        text = value.strip()
        if text.startswith("<?xml") or text.startswith("<nmaprun"):
            return text
        return None
    if isinstance(value, dict):
        for item in value.values():
            found = find_xml(item)
            if found:
                return found
    elif isinstance(value, list):
        for item in value:
            found = find_xml(item)
            if found:
                return found
    return None


def find_text(value, pattern):
    if isinstance(value, str):
        match = re.search(pattern, value, re.MULTILINE)
        return match.group(0) if match else None
    if isinstance(value, dict):
        for item in value.values():
            found = find_text(item, pattern)
            if found:
                return found
    elif isinstance(value, list):
        for item in value:
            found = find_text(item, pattern)
            if found:
                return found
    return None


def main():
    try:
        from framework_evidence import run_tool
    except Exception as exc:
        print(json.dumps({"error": "Unable to load supplied framework_evidence helper", "detail": str(exc)}))
        return 2

    scan_argv = ["nmap", "-sV", "-p-", "-oX", "-", TARGET]
    try:
        scan = as_object(run_tool(scan_argv))
    except Exception as exc:
        print(json.dumps({"scan_command": scan_argv, "error": str(exc)}))
        return 2
    print(json.dumps({"evidence": "service_identification", "envelope": scan}, ensure_ascii=False))

    xml_text = find_xml(scan)
    if not xml_text:
        print(json.dumps({"result": "origin_not_established", "reason": "Nmap XML output was unavailable; scan coverage or parsing is incomplete."}))
        return 0
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        print(json.dumps({"result": "origin_not_established", "reason": "Nmap XML could not be parsed.", "parse_error": str(exc)}))
        return 0

    candidates = []
    for port in root.findall(".//port"):
        state = port.find("state")
        service = port.find("service")
        if state is None or state.get("state") != "open" or service is None:
            continue
        name = service.get("name", "").lower()
        product = service.get("product", "").lower()
        tunnel = service.get("tunnel", "").lower()
        if "http" not in name and "http" not in product:
            continue
        number = int(port.get("portid", "0"))
        scheme = "https" if tunnel == "ssl" or name == "https" or name.startswith("ssl/") else "http"
        candidates.append((number, scheme, name, product))

    if not candidates:
        print(json.dumps({"result": "origin_not_established", "reason": "The available Nmap service-identification output contained no open service identified as HTTP(S).", "scan_finished": root.get("runstats") is not None}))
        return 0

    for port, scheme, service_name, product in candidates:
        default_port = 443 if scheme == "https" else 80
        origin = scheme + "://" + TARGET + ("" if port == default_port else ":" + str(port))
        url = origin + "/"
        curl_argv = ["curl", "-sS", "-D", "-", "-o", "/dev/null", "--max-time", "10"]
        if scheme == "https":
            curl_argv.append("-k")
        curl_argv.append(url)
        record = {"candidate": {"scheme": scheme, "port": port, "origin": origin, "nmap_service": service_name, "product": product}, "request_command": curl_argv}
        try:
            response = as_object(run_tool(curl_argv))
            record["response_envelope"] = response
            status_line = find_text(response, r"^HTTP/[^\r\n]+")
            record["http_status_line"] = status_line
            record["responsive_http"] = bool(status_line)
            record["assessment"] = "HTTP response observed" if status_line else "No HTTP status line observed; origin responsiveness is unconfirmed"
        except Exception as exc:
            record["request_error"] = str(exc)
            record["responsive_http"] = False
            record["assessment"] = "Request failed; origin responsiveness is unconfirmed"
        print(json.dumps(record, ensure_ascii=False))

    return 0


if __name__ == "__main__":
    sys.exit(main())

