import json
import re
import sys

from framework_evidence import run_tool

ORIGIN = "http://192.168.2.0"
OPTIONS_ARGV = ["curl", "-sS", "-i", "--max-time", "10", "-X", "OPTIONS", ORIGIN + "/"]
PROPFIND_BODY = (
    '<?xml version="1.0" encoding="utf-8"?>'
    '<D:propfind xmlns:D="DAV:"><D:prop>'
    '<D:displayname/><D:resourcetype/>'
    '</D:prop></D:propfind>'
)


def response_text(envelope):
    """Collect raw stdout from the helper envelope without discarding it."""
    if not isinstance(envelope, dict):
        return ""
    runs = envelope.get("tool_runs", [])
    if not isinstance(runs, list):
        return ""
    return "\n".join(
        run.get("stdout", "")
        for run in runs
        if isinstance(run, dict) and isinstance(run.get("stdout", ""), str)
    )


def header_blocks(raw):
    """Return response-header blocks from curl -i output, including interim blocks."""
    blocks = []
    current = None
    for line in raw.splitlines():
        if re.match(r"^HTTP/\S+\s+\d{3}\b", line, re.IGNORECASE):
            current = {"status_line": line, "headers": {}}
            blocks.append(current)
            continue
        if current is None:
            continue
        if not line.strip():
            current = None
            continue
        if ":" in line:
            name, value = line.split(":", 1)
            current["headers"].setdefault(name.strip().lower(), []).append(value.strip())
    return blocks


def capability_evidence(raw):
    blocks = header_blocks(raw)
    indicators = []
    for block in blocks:
        headers = block["headers"]
        dav_values = headers.get("dav", [])
        if any(value.strip() for value in dav_values):
            indicators.append({"kind": "DAV header", "values": dav_values})
        author_values = headers.get("ms-author-via", [])
        if any(re.search(r"\bDAV\b", value, re.IGNORECASE) for value in author_values):
            indicators.append({"kind": "MS-Author-Via indicates DAV", "values": author_values})
        allow_values = headers.get("allow", [])
        if any(re.search(r"(?:^|[,\s])PROPFIND(?:$|[,\s])", value, re.IGNORECASE) for value in allow_values):
            indicators.append({"kind": "Allow advertises PROPFIND", "values": allow_values})
        link_values = headers.get("link", [])
        collection_links = [
            value for value in link_values
            if re.search(r"\brel\s*=\s*(?:\"[^\"]*\bcollection\b[^\"]*\"|'[^']*\bcollection\b[^']*'|collection)\b", value, re.IGNORECASE)
        ]
        if collection_links:
            indicators.append({"kind": "Link advertises collection relation", "values": collection_links})
    return {"header_blocks": blocks, "indicators": indicators, "supports_readonly_collection_discovery": bool(indicators)}


def main():
    result = {
        "origin": ORIGIN,
        "requests": [],
        "coverage_note": "Only root OPTIONS was requested; PROPFIND is conditional on explicit capability evidence in its response.",
    }
    result["requests"].append({"purpose": "request supported-method and capability information", "argv": OPTIONS_ARGV})
    try:
        options_envelope = run_tool(OPTIONS_ARGV)
    except Exception as exc:
        result["requests"][0]["error"] = {"type": type(exc).__name__, "message": str(exc)}
        print(json.dumps(result, ensure_ascii=False))
        return
    result["requests"][0]["response_envelope"] = options_envelope
    options_raw = response_text(options_envelope)
    capability = capability_evidence(options_raw)
    result["options_assessment"] = capability

    if capability["supports_readonly_collection_discovery"]:
        propfind_argv = [
            "curl", "-sS", "-i", "--max-time", "10", "-X", "PROPFIND",
            "-H", "Depth: 1",
            "-H", "Content-Type: application/xml",
            "--data-binary", PROPFIND_BODY,
            ORIGIN + "/",
        ]
        result["requests"].append({
            "purpose": "read-only collection discovery, conditional on observed capability evidence",
            "argv": propfind_argv,
            "triggering_indicators": capability["indicators"],
        })
        try:
            result["requests"][1]["response_envelope"] = run_tool(propfind_argv)
        except Exception as exc:
            result["requests"][1]["error"] = {"type": type(exc).__name__, "message": str(exc)}
    else:
        result["collection_discovery"] = "Not issued: the captured OPTIONS response did not explicitly indicate WebDAV or a collection interface."

    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()
